  useEffect(() => {
    if (
      isPlaying ||
      (editorMode !== "stage" && editorMode !== "ui_stage")
    ) {
      setIsCanvasResizeMode(false);
      setIsResizingCanvas(null);
    }
  }, [editorMode, isPlaying]);

  useEffect(() => {
    if (!isResizingCanvas) return;

    const handlePointerMove = (e: PointerEvent) => {
      const dx = e.clientX - isResizingCanvas.startX;
      const dy = e.clientY - isResizingCanvas.startY;

      const canvasDx = Math.round(dx / stageZoom);
      const canvasDy = Math.round(dy / stageZoom);

      let newWidth = isResizingCanvas.startWidth;
      let newHeight = isResizingCanvas.startHeight;

      if (isResizingCanvas.direction === "r" || isResizingCanvas.direction === "br") {
        newWidth = Math.max(100, Math.min(4000, isResizingCanvas.startWidth + canvasDx));
      }
      if (isResizingCanvas.direction === "b" || isResizingCanvas.direction === "br") {
        newHeight = Math.max(100, Math.min(4000, isResizingCanvas.startHeight + canvasDy));
      }

      if (isResizingCanvas.direction === "br" && e.shiftKey) {
        // Proportional resizing
        const aspect = isResizingCanvas.startWidth / isResizingCanvas.startHeight;
        if (newWidth / aspect > newHeight) {
          newHeight = Math.round(newWidth / aspect);
        } else {
          newWidth = Math.round(newHeight * aspect);
        }
      }

      setProject((p) => {
        const updatedScenes = p.scenes.map((s) => {
          if (s.id === p.currentSceneId) {
            return { ...s, width: newWidth, height: newHeight };
          }
          return s;
        });
        return {
          ...p,
          globalSettings: {
            ...p.globalSettings,
            stageWidth: newWidth,
            stageHeight: newHeight,
          },
          scenes: updatedScenes,
        };
      });
    };

    const handlePointerUp = () => {
      setIsResizingCanvas(null);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);

    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
    };
  }, [isResizingCanvas, stageZoom]);

  const handleSaveToSlot = async (slotId: number) => {
    try {
      setSaveStatus("saving");
      const strippedProject = stripDuplicatedAssetSources(project);

      await set(saveSlotStorageKey(slotId), strippedProject);
      try {
        localStorage.setItem(saveSlotStorageKey(slotId), JSON.stringify(strippedProject));
      } catch (storageErr) {
        console.warn("Could not mirror save slot to localStorage", storageErr);
      }

      const timestamp = new Date().toLocaleString();
      const newMeta: SaveSlotMeta = {
        slotId,
        projectName: project.name || "Untitled Game",
        timestamp,
        savedSceneCount: project.scenes?.length || 0,
        gameFlagCount: project.gameFlags?.length || 0,
        timeMs: Date.now(),
      };

      setSaveSlotsMeta((prev) => {
        const updated = prev.filter((s) => s.slotId !== slotId);
        updated.push(newMeta);
        updated.sort((a, b) => a.slotId - b.slotId);
        localStorage.setItem(SAVE_SLOTS_META_KEY, JSON.stringify(updated));
        return updated;
      });

      setSaveStatus("saved");
      showError(`Saved project version to Slot ${slotId}!`);
    } catch (err) {
      console.error("Failed to save to slot", err);
      setSaveStatus("error");
      showError(`Failed to save to Slot ${slotId}.`);
    }
  };

  const buildSlotMeta = (slotId: number, savedProject: any): SaveSlotMeta => ({
    slotId,
    projectName: savedProject?.name || `Recovered Slot ${slotId}`,
    timestamp: savedProject?.updatedAt
      ? new Date(savedProject.updatedAt).toLocaleString()
      : "Recovered from local data",
    savedSceneCount: savedProject?.scenes?.length || 0,
    gameFlagCount: savedProject?.gameFlags?.length || 0,
    timeMs: savedProject?.updatedAt
      ? new Date(savedProject.updatedAt).getTime()
      : Date.now() - (5 - slotId),
  });

  useEffect(() => {
    let cancelled = false;
    const recoverSlotMetadata = async () => {
      try {
        const recovered: SaveSlotMeta[] = [];
        for (const slotId of [1, 2, 3, 4, 5]) {
          let saved = await get(saveSlotStorageKey(slotId));
          if (!saved) {
            const localSaved = localStorage.getItem(saveSlotStorageKey(slotId));
            if (localSaved) saved = JSON.parse(localSaved);
          }
          if (saved) recovered.push(buildSlotMeta(slotId, saved));
        }
        if (cancelled || recovered.length === 0) return;
        setSaveSlotsMeta((current) => {
          const merged = [...current];
          recovered.forEach((meta) => {
            if (!merged.some((existing) => existing.slotId === meta.slotId)) {
              merged.push(meta);
            }
          });
          merged.sort((a, b) => a.slotId - b.slotId);
          localStorage.setItem(SAVE_SLOTS_META_KEY, JSON.stringify(merged));
          return merged;
        });
      } catch (err) {
        console.warn("Could not recover save slot metadata", err);
      }
    };
    void recoverSlotMetadata();
    return () => {
      cancelled = true;
    };
  }, []);

  const handleLoadFromSlot = async (slotId: number) => {
    try {
      let saved = await get(saveSlotStorageKey(slotId));
      if (!saved) {
        const localSaved = localStorage.getItem(saveSlotStorageKey(slotId));
        if (localSaved) saved = JSON.parse(localSaved);
      }
      if (saved) {
        restoreProjectSnapshot(saved);
        showError(`Restored Slot ${slotId} project version successfully!`);
      } else {
        showError(`No saved project version found in Slot ${slotId}.`);
      }
    } catch (err) {
      console.error("Failed to load from slot", err);
      showError(`Failed to load project from Slot ${slotId}.`);
    }
  };

  const handleDeleteSlot = async (slotId: number) => {
    try {
      await del(saveSlotStorageKey(slotId));
      localStorage.removeItem(saveSlotStorageKey(slotId));
      setSaveSlotsMeta((prev) => {
        const updated = prev.filter((s) => s.slotId !== slotId);
        localStorage.setItem(SAVE_SLOTS_META_KEY, JSON.stringify(updated));
        return updated;
      });
      showError(`Cleared Slot ${slotId} backup.`);
    } catch (err) {
      console.error("Failed to delete slot info", err);
      showError(`Failed to clear Slot ${slotId}.`);
    }
  };

  const showError = (msg: string) => {
    setEditorError(msg);
    setTimeout(() => setEditorError(null), 5000);
  };

  const pushHistory = (newProj: Project) => {
    setHistory((h) => ({ past: [...h.past.slice(-20), project], future: [] }));
    setProject(newProj);
  };

  const undo = () => {
    if (history.past.length === 0) return;
    const previous = history.past[history.past.length - 1];
    setHistory((h) => ({
      past: h.past.slice(0, -1),
      future: [project, ...h.future],
    }));
    setProject(previous);
  };

  const redo = () => {
    if (history.future.length === 0) return;
    const next = history.future[0];
    setHistory((h) => ({
      past: [...h.past, project],
      future: h.future.slice(1),
    }));
    setProject(next);
  };

  const hydrateProject = (parsed: any): Project => {
    const referencedAssetValues = new Set<string>();
    const collectReferencedValues = (value: unknown) => {
      if (typeof value === "string") {
        referencedAssetValues.add(value);
        return;
      }
      if (Array.isArray(value)) {
        value.forEach(collectReferencedValues);
        return;
      }
      if (value && typeof value === "object") {
        Object.entries(value as Record<string, unknown>).forEach(
          ([key, child]) => {
            if (key !== "assets") collectReferencedValues(child);
          },
        );
      }
    };
    collectReferencedValues(parsed);
	    const assets = (parsed.assets || [])
	      .map((asset: Asset) => normalizeAssetForRuntime(asset))
	      .filter((asset: Asset) => {
	      const isRepositoryAsset =
	        asset.id?.startsWith("github:") ||
        asset.src?.includes(
          "raw.githubusercontent.com/thenabu222/entropic-ai/",
        );
      if (!isRepositoryAsset) return true;
      return (
        asset.isFavorite ||
	        referencedAssetValues.has(asset.id) ||
	        referencedAssetValues.has(asset.src) ||
	        referencedAssetValues.has(asset.dataURL || "")
	      );
	    });
	    const hydrateObjectAsset = (o: any) => {
	      const assetId = o._assetId || o.assetId;
	      if (assetId) {
	        const asset = assets.find((a: any) => a.id === assetId);
	        if (asset) {
            return {
              ...o,
              _assetId: assetId,
              src: o.src || getAssetDisplaySrc(asset),
            };
          }
	      }
	      return o;
	    };
      const importedStageWidth =
        parsed.globalSettings?.stageWidth ||
        parsed.canvasWidth ||
        parsed.scenes?.[0]?.width ||
        800;
      const importedStageHeight =
        parsed.globalSettings?.stageHeight ||
        parsed.canvasHeight ||
        parsed.scenes?.[0]?.height ||
        600;
      const hydrateScene = (scene: any) => ({
        ...scene,
        width: scene.width || importedStageWidth,
        height: scene.height || importedStageHeight,
        backgroundColor:
          scene.backgroundColor || scene.bgColor || "transparent",
        objects: (scene.objects || []).map(hydrateObjectAsset),
      });
	    return {
	      ...parsed,
        id: parsed.id || `imported-${Date.now()}`,
        currentSceneId: parsed.currentSceneId || parsed.activeSceneId,
	      prefabs: (parsed.prefabs || []).map(hydrateObjectAsset),
      dialogueTrees: parsed.dialogueTrees
        ? parsed.dialogueTrees.map((t: any) => ({
            ...t,
            startNodeId:
              t.startNodeId &&
              (t.nodes || []).some((n: any) => n.id === t.startNodeId)
                ? t.startNodeId
                : (t.nodes || [])[0]?.id || null,
            nodes: t.nodes
              ? t.nodes.map((n: any) => ({
                  ...n,
                  choices: n.choices || [],
                }))
              : [],
          }))
        : [],
      inventoryItems: parsed.inventoryItems || [],
      assets: assets,
      scenes: parsed.scenes
        ? parsed.scenes.map(hydrateScene)
        : [],
      uiMenus: parsed.uiMenus
        ? parsed.uiMenus.map(hydrateScene)
        : [],
      maps: (parsed.maps || []).map((map: any, index: number) => ({
        id: map.id || `map-${index + 1}`,
        name: map.name || `World Map ${index + 1}`,
        backgroundSrc: map.backgroundSrc || null,
        ...map,
        nodes: Array.isArray(map.nodes) ? map.nodes : [],
      })),
      loreEntries: parsed.loreEntries || [],
      factions: parsed.factions || [],
      companions: parsed.companions || [],
      characters: parsed.characters || [],
      currentUiMenuId: parsed.currentUiMenuId || null,
      globalSettings: {
        ...(parsed.globalSettings || {}),
        stageWidth: importedStageWidth,
        stageHeight: importedStageHeight,
      },
    };
  };

  const normalizeRestoredProject = (parsed: any, fallback: Project): Project => {
    const hydrated = hydrateProject(parsed);
    const scenes =
      hydrated.scenes && hydrated.scenes.length > 0
        ? hydrated.scenes
        : fallback.scenes;
    const uiMenus = hydrated.uiMenus || [];
    const currentSceneId = scenes.some((scene) => scene.id === hydrated.currentSceneId)
      ? hydrated.currentSceneId
      : scenes[0]?.id || fallback.currentSceneId;
    const currentUiMenuId =
      hydrated.currentUiMenuId &&
      uiMenus.some((menu) => menu.id === hydrated.currentUiMenuId)
        ? hydrated.currentUiMenuId
        : uiMenus[0]?.id || null;

    return {
      ...fallback,
      ...hydrated,
      scenes,
      uiMenus,
      currentSceneId,
      currentUiMenuId,
      assets: hydrated.assets || [],
      dialogueTrees: hydrated.dialogueTrees || [],
      inventoryItems: hydrated.inventoryItems || [],
      craftingRecipes: hydrated.craftingRecipes || [],
      quests: hydrated.quests || [],
      maps: hydrated.maps || [],
      gameFlags: hydrated.gameFlags || [],
      loreEntries: hydrated.loreEntries || [],
      factions: hydrated.factions || [],
      companions: hydrated.companions || [],
      characters: hydrated.characters || [],
      globalSettings: {
        ...fallback.globalSettings,
        ...(hydrated.globalSettings || {}),
      },
    };
  };

  const persistRestoredProject = async (restoredProject: Project) => {
    const strippedProject = stripDuplicatedAssetSources(restoredProject);
    const autosaveProject = stripAssetLibraryForAutosave(strippedProject);
    await set(PROJECT_STORAGE_KEY, autosaveProject);
    await set(PROJECT_ASSET_LIBRARY_STORAGE_KEY, autosaveProject.assets || []);
    lastAutosavedAssetsRef.current = autosaveProject.assets || [];
    try {
      const serializedProject = JSON.stringify(autosaveProject);
      if (serializedProject.length < 4_500_000) {
        localStorage.setItem(PROJECT_STORAGE_KEY, serializedProject);
      } else {
        localStorage.removeItem(PROJECT_STORAGE_KEY);
      }
      localStorage.removeItem(PROJECT_ASSET_LIBRARY_STORAGE_KEY);
    } catch (storageErr) {
      console.warn("Could not mirror restored project to localStorage", storageErr);
    }
  };

  const restoreProjectSnapshot = (snapshot: any) => {
    setSaveStatus("saving");
    const restoredProject = normalizeRestoredProject(snapshot, project);
    setProject(restoredProject);
    void persistRestoredProject(restoredProject)
      .then(() => setSaveStatus("saved"))
      .catch((err) => {
        console.error("Failed to persist restored project", err);
        setSaveStatus("error");
        showError("Project restored, but saving it locally failed.");
      });
    setHistory({ past: [], future: [] });
    setSelectedObjectId(null);
    setSelectedMultiIds([]);
    setIsPlaying(false);
  };

  const mergeImportedProjectIntoCurrent = (incoming: any) => {
    const normalizedIncoming = normalizeRestoredProject(incoming, project);
    const mergedProject: Project = {
      ...project,
      assets: mergeImportedList(project.assets || [], normalizedIncoming.assets || []),
      scenes: mergeImportedList(project.scenes || [], normalizedIncoming.scenes || []),
      uiMenus: mergeImportedList(project.uiMenus || [], normalizedIncoming.uiMenus || []),
      dialogueTrees: mergeImportedList(
        project.dialogueTrees || [],
        normalizedIncoming.dialogueTrees || [],
      ),
      inventoryItems: mergeImportedList(
        project.inventoryItems || [],
        normalizedIncoming.inventoryItems || [],
      ),
      craftingRecipes: mergeImportedList(
        project.craftingRecipes || [],
        normalizedIncoming.craftingRecipes || [],
      ),
      quests: mergeImportedList(project.quests || [], normalizedIncoming.quests || []),
      maps: mergeImportedList(project.maps || [], normalizedIncoming.maps || []),
      loreEntries: mergeImportedList(
        project.loreEntries || [],
        normalizedIncoming.loreEntries || [],
      ),
      factions: mergeImportedList(
        project.factions || [],
        normalizedIncoming.factions || [],
      ),
      companions: mergeImportedList(
        project.companions || [],
        normalizedIncoming.companions || [],
      ),
      characters: mergeImportedList(
        project.characters || [],
        normalizedIncoming.characters || [],
      ),
      gameFlags: Array.from(
        new Set([...(project.gameFlags || []), ...(normalizedIncoming.gameFlags || [])]),
      ),
      globalSettings: {
        ...project.globalSettings,
        ...(normalizedIncoming.globalSettings || {}),
      },
    };
    pushHistory(mergedProject);
    setIsPlaying(false);
    showError("JSON merged into the current game.");
  };

  // Load from IndexedDB (fallback to LocalStorage) on mount
  useEffect(() => {
    const loadProject = async () => {
      try {
        const restoreFile = new URLSearchParams(window.location.search).get(
          "restore",
        );
        if (restoreFile) {
          const response = await fetch(`/${restoreFile}`, { cache: "no-store" });
          if (!response.ok) {
            throw new Error(`Restore file failed to load: ${response.status}`);
          }
          const restoredFromFile = normalizeRestoredProject(
            await response.json(),
            project,
          );
          setProject(restoredFromFile);
          await persistRestoredProject(restoredFromFile);
          setHasLoadedStoredProject(true);
          window.history.replaceState(
            {},
            document.title,
            window.location.pathname,
          );
          showError(`Imported ${restoreFile}.`);
          return;
        }

        let saved = await get(PROJECT_STORAGE_KEY);
        if (!saved) {
          const localSaved = localStorage.getItem(PROJECT_STORAGE_KEY);
          if (localSaved) {
            saved = JSON.parse(localSaved);
          }
        }
        if (saved) {
          const restoredShellAssets = Array.isArray(saved.assets)
            ? saved.assets.map((asset: Asset) => normalizeAssetForRuntime(asset))
            : [];
          setProject((prev) =>
            normalizeRestoredProject(
              {
                ...saved,
                assets: restoredShellAssets,
              },
              prev,
            ),
          );
          lastAutosavedAssetsRef.current = restoredShellAssets;
          setHasLoadedStoredProject(true);
        } else {
          setHasLoadedStoredProject(true);
        }
      } catch (e) {
        console.error("Failed to load project", e);
        setHasLoadedStoredProject(true);
      }
    };
    loadProject();
  }, []);

  useEffect(() => {
    if (!hasLoadedStoredProject) return;
    const entries = collectScenePreloadEntries(project).filter(
      (entry) => !preloadedSceneAssetSrcsRef.current.has(entry.src),
    );
    if (!entries.length) return;

    let cancelled = false;
    entries.forEach((entry) => preloadedSceneAssetSrcsRef.current.add(entry.src));

    const preloadInBatches = async () => {
      const batchSize = 12;
      let failed = 0;
      for (let index = 0; index < entries.length; index += batchSize) {
        const batch = entries.slice(index, index + batchSize);
        const results = await Promise.all(
          batch.map((entry) =>
            preloadAssetEntry(entry).then((ok) => ({ entry, ok })),
          ),
        );
        if (cancelled) return;
        results.forEach(({ entry, ok }) => {
          if (!ok) {
            failed += 1;
            preloadedSceneAssetSrcsRef.current.delete(entry.src);
          }
        });
      }
      if (failed) {
        console.warn(
          `Cavebot preload skipped ${failed} scene asset${
            failed === 1 ? "" : "s"
          } that could not be reached.`,
        );
      } else {
        console.info(
          `Cavebot preloaded ${entries.length} scene asset${
            entries.length === 1 ? "" : "s"
          }.`,
        );
      }
    };

    void preloadInBatches();
    return () => {
      cancelled = true;
    };
  }, [
    hasLoadedStoredProject,
    project.assets,
    project.scenes,
    project.uiMenus,
    project.globalSettings.customCursorAssetId,
    project.globalSettings.deviceFrame?.assetId,
    project.globalSettings.hudOverlay?.assetId,
  ]);

  // Save to IndexedDB on change
  useEffect(() => {
    if (!hasLoadedStoredProject) return;
    const saveProject = async () => {
      setSaveStatus("saving");
      try {
        const strippedProject = stripDuplicatedAssetSources(project);
        const autosaveProject = stripAssetLibraryForAutosave(strippedProject);
        await set(PROJECT_STORAGE_KEY, autosaveProject);
        if (lastAutosavedAssetsRef.current !== autosaveProject.assets) {
          await set(PROJECT_ASSET_LIBRARY_STORAGE_KEY, autosaveProject.assets || []);
          localStorage.removeItem(PROJECT_ASSET_LIBRARY_STORAGE_KEY);
          lastAutosavedAssetsRef.current = autosaveProject.assets || [];
        }
        setSaveStatus("saved");
      } catch (e) {
        console.error("Failed to save project to IndexedDB", e);
        setSaveStatus("error");
        showError("Failed to save project. Storage quota may be exceeded.");
      }
    };

    // Debounce save slightly to avoid thrashing
    const timeoutId = setTimeout(saveProject, 2000);
    return () => clearTimeout(timeoutId);
  }, [hasLoadedStoredProject, project]);

  const handleExportProject = (
    mode: "used" | "references" | "library" = "used",
  ) => {
    try {
      const strippedProject = prepareProjectForExport(project, {
        assetScope: mode === "library" ? "all" : "used",
        includeEmbeddedAssetData:
          mode === "references" ? false : true,
        keepFavoriteAssets: mode === "library",
      });
      const jsonStr = JSON.stringify(strippedProject);
      const blob = new Blob([jsonStr], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const suffix =
        mode === "library"
          ? "full_library_backup"
          : mode === "references"
            ? "repo_refs_backup"
            : "backup";
      const downloadAnchorNode = document.createElement("a");
      downloadAnchorNode.setAttribute("href", url);
      downloadAnchorNode.setAttribute(
        "download",
        `${project.name.replace(/\s+/g, "_")}_${suffix}.json`,
      );
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      document.body.removeChild(downloadAnchorNode);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      showError(
        mode === "library"
          ? "Exported full-library JSON."
          : mode === "references"
            ? "Exported repo-reference JSON without embedded base64."
            : "Exported self-contained JSON with all used asset data.",
      );
    } catch (err) {
      showError("Failed to export project: " + err);
    }
  };

  const handleImportProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        let content = event.target?.result as string;
        if (file.name.endsWith(".html")) {
          const gameDataMatch = content.match(
            /<script\b(?=[^>]*\bid=["']__GAME_DATA__["'])(?=[^>]*\btype=["']application\/json["'])[^>]*>([\s\S]*?)<\/script>/i,
          );
          if (gameDataMatch?.[1]) {
            content = gameDataMatch[1].trim();
          } else {
            showError("No embedded project data found in HTML.");
            return;
          }
        }
        const parsed = JSON.parse(content);
        if (parsed && Array.isArray(parsed.scenes)) {
          mergeImportedProjectIntoCurrent(parsed);
        } else {
          showError("Invalid project file format.");
        }
      } catch (err) {
        showError("Failed to parse project file.");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const bgmRef = useRef<HTMLAudioElement | null>(null);

  const playRuntimeAudioAsset = (audioAsset?: Asset | null) => {
    const audioSrc = getAssetDisplaySrc(audioAsset);
    if (!audioAsset || !audioSrc || isAudioMuted) return;
    const mediaFragment =
      audioAsset.trimStart || audioAsset.trimEnd
        ? `#t=${audioAsset.trimStart || 0}${audioAsset.trimEnd ? `,${audioAsset.trimEnd}` : ""}`
        : "";
    const audio = new Audio(audioSrc + mediaFragment);
    audio.volume = Math.min(1, audioAsset.volume ?? 1);
    audio.muted = isAudioMuted;
    runtimeAudioRefs.current = runtimeAudioRefs.current
      .filter((candidate) => !candidate.paused)
      .concat(audio);
    audio.play().catch((e) => console.error("SFX playback failed", e));
  };

  useEffect(() => {
    const currentScene = project.scenes.find(
      (s) => s.id === project.currentSceneId,
    );
    if (isPlaying && currentScene?.bgmAssetId) {
      const audioAsset = project.assets.find(
        (a) => a.id === currentScene.bgmAssetId,
      );
      const audioSrc = getAssetDisplaySrc(audioAsset);
      if (audioAsset && audioSrc) {
        const mediaFragment = audioAsset.trimStart || audioAsset.trimEnd ? `#t=${audioAsset.trimStart || 0}${audioAsset.trimEnd ? ',' + audioAsset.trimEnd : ''}` : '';
        const fullSrc = audioSrc + mediaFragment;
        if (!bgmRef.current) {
          bgmRef.current = new Audio(fullSrc);
          bgmRef.current.loop = true;
          bgmRef.current.volume = Math.min(1, audioAsset.volume ?? 1);
          bgmRef.current.muted = isAudioMuted;
        } else if (
          bgmRef.current.src !== fullSrc ||
          bgmRef.current.volume !== Math.min(1, audioAsset.volume ?? 1)
        ) {
          bgmRef.current.pause();
          bgmRef.current = new Audio(fullSrc);
          bgmRef.current.loop = true;
          bgmRef.current.volume = Math.min(1, audioAsset.volume ?? 1);
          bgmRef.current.muted = isAudioMuted;
        }
        bgmRef.current.muted = isAudioMuted;
        bgmRef.current
          .play()
          .catch((e) => console.error("Audio playback failed", e));
      }
    } else {
      if (bgmRef.current) {
        bgmRef.current.pause();
      }
    }

    return () => {
      if (!isPlaying && bgmRef.current) {
        bgmRef.current.pause();
      }
    };
  }, [isPlaying, isAudioMuted, project.currentSceneId, project.assets, project.scenes]);

  useEffect(() => {
    let timeInterval: ReturnType<typeof setInterval> | null = null;
    if (isPlaying && project.globalSettings.useDayNightCycle) {
      const hoursPerTick = Math.max(
        0,
        project.globalSettings.dayNightHoursPerTick ?? 0.1,
      );
      const tickMs = Math.max(100, project.globalSettings.dayNightTickMs ?? 1000);
      timeInterval = setInterval(() => {
        setGameTime((prev) => {
          const next = prev + hoursPerTick;
          if (next >= 24) {
            const daysElapsed = Math.floor(next / 24);
            setGameDay((day) => day + Math.max(1, daysElapsed));
            return next % 24;
          }
          return next;
        });

        // Deplete needs over time if enabled
        if (project.globalSettings.enableNeeds) {
          setPlayerNeeds(prev => {
            const next = { ...prev };
            if (next.rest) next.rest = Math.max(0, next.rest - 1); // Rest decreases faster
            if (next.hunger) next.hunger = Math.max(0, next.hunger - 0.5);
            if (next.connection) next.connection = Math.max(0, next.connection - 0.2);
            if (next.spiritual) next.spiritual = Math.max(0, next.spiritual - 0.1);
            if (next.novelty) next.novelty = Math.max(0, next.novelty - 0.3);
            return next;
          });
        }
      }, tickMs);
    }
    return () => {
      if (timeInterval) clearInterval(timeInterval);
    };
  }, [
    isPlaying,
    project.globalSettings.dayNightHoursPerTick,
    project.globalSettings.dayNightTickMs,
    project.globalSettings.enableNeeds,
    project.globalSettings.useDayNightCycle,
  ]);

  useEffect(() => {
    if (isPlaying) {
      const engine = Matter.Engine.create();
      const runner = Matter.Runner.create();
      const bodies: Record<string, Matter.Body> = {};

      const ground = Matter.Bodies.rectangle(
        project.globalSettings.stageWidth / 2,
        project.globalSettings.stageHeight + 25,
        project.globalSettings.stageWidth,
        50,
        { isStatic: true },
      );
      const leftWall = Matter.Bodies.rectangle(
        -25,
        project.globalSettings.stageHeight / 2,
        50,
        project.globalSettings.stageHeight,
        { isStatic: true },
      );
      const rightWall = Matter.Bodies.rectangle(
        project.globalSettings.stageWidth + 25,
        project.globalSettings.stageHeight / 2,
        50,
        project.globalSettings.stageHeight,
        { isStatic: true },
      );
      Matter.Composite.add(engine.world, [ground, leftWall, rightWall]);

      const currentScene = project.scenes.find(
        (s) => s.id === project.currentSceneId,
      );
      if (currentScene) {
        currentScene.objects.forEach((obj) => {
          if (obj.hasPhysics) {
            const body = Matter.Bodies.rectangle(
              obj.x + obj.width / 2,
              obj.y + obj.height / 2,
              obj.width,
              obj.height,
              {
                isStatic: !!obj.physicsStatic,
                restitution: obj.physicsBounciness ?? 0.6,
                friction: obj.physicsFriction ?? 0.1,
                density: obj.physicsDensity ?? 0.05,
              },
            );
            Matter.Body.setAngle(body, obj.rotation * (Math.PI / 180));
            bodies[obj.id] = body;
            Matter.Composite.add(engine.world, body);
          }
        });
      }

      let mouseConstraint: any = null;
      if (stageRef.current) {
        const mouse = Matter.Mouse.create(stageRef.current);
        mouseConstraint = Matter.MouseConstraint.create(engine, {
          mouse: mouse,
          constraint: {
            stiffness: 0.2,
            render: {
              visible: false,
            },
          },
        });
        Matter.Composite.add(engine.world, mouseConstraint);
      }

      Matter.Runner.run(runner, engine);

      let animationFrameId: number;
      const updatePhysics = () => {
        const newPhysicsState: Record<
          string,
          { x: number; y: number; rotation: number }
        > = {};
        for (const id in bodies) {
          const body = bodies[id];
          const obj = currentScene?.objects.find((o) => o.id === id);
          if (obj) {
            newPhysicsState[id] = {
              x: body.position.x - obj.width / 2,
              y: body.position.y - obj.height / 2,
              rotation: body.angle * (180 / Math.PI),
            };
          }
        }
        setPhysicsState(newPhysicsState);
        animationFrameId = requestAnimationFrame(updatePhysics);
      };
      updatePhysics();

      return () => {
        cancelAnimationFrame(animationFrameId);
        if (mouseConstraint) {
          Matter.Mouse.clearSourceEvents(mouseConstraint.mouse);
        }
        Matter.Runner.stop(runner);
        Matter.Engine.clear(engine);
      };
    } else {
      setPhysicsState({});
    }
  }, [isPlaying, project.currentSceneId]);

  // Dragging state for stage objects
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const draggingIdRef = useRef<string | null>(null);
  const dragOffsetRef = useRef({ x: 0, y: 0 });

  // Parallax tracking state
  const [mouseRatio, setMouseRatio] = useState({ x: 0, y: 0 });

  const stageRef = useRef<HTMLDivElement>(null);
  type HudWidgetId = "needs" | "skills" | "buttons";
  type HudPositionKey =
    | "hudNeedsPosition"
    | "hudSkillsPosition"
    | "hudButtonsPosition";
  const [selectedHudWidget, setSelectedHudWidget] =
    useState<HudWidgetId | null>(null);
  const [isHudPlacementMode, setIsHudPlacementMode] = useState(false);
  const [draggingHudWidget, setDraggingHudWidget] = useState<{
    key: HudPositionKey;
    pointerId: number;
    startClientX: number;
    startClientY: number;
    startX: number;
    startY: number;
    width: number;
    height: number;
  } | null>(null);
  type HudResizeState = {
    widget: HudWidgetId;
    pointerId: number;
    axis: "x" | "y" | "xy";
    startX: number;
    startY: number;
    startScaleX: number;
    startScaleY: number;
    renderedWidth: number;
    renderedHeight: number;
  };
  const resizingHudWidgetRef = useRef<HudResizeState | null>(null);

  const getHudWidgetConfig = (widget: HudWidgetId) => {
    if (widget === "needs") {
      return {
        label: "Needs panel",
        positionKey: "hudNeedsPosition" as const,
        scaleXKey: "hudNeedsScaleX" as const,
        scaleYKey: "hudNeedsScaleY" as const,
      };
    }
    if (widget === "skills") {
      return {
        label: "Skills panel",
        positionKey: "hudSkillsPosition" as const,
        scaleXKey: "hudSkillsScaleX" as const,
        scaleYKey: "hudSkillsScaleY" as const,
      };
    }
    return {
      label: "Built-in buttons",
      positionKey: "hudButtonsPosition" as const,
      scaleXKey: "hudButtonsScaleX" as const,
      scaleYKey: "hudButtonsScaleY" as const,
    };
  };

  const selectHudWidget = (widget: HudWidgetId) => {
    if (isPlaying) return;
    if (rightSidebarWidth === 0) setRightSidebarWidth(320);
    setSelectedHudWidget(widget);
    setSelectedObjectId(null);
    setSelectedMultiIds([]);
    setRightSidebarTab("properties");
    window.dispatchEvent(
      new CustomEvent("open-accordion", {
        detail: { title: "Heads Up Display (HUD)" },
      }),
    );
  };

  const handleHudWidgetPointerDown = (
    event: React.PointerEvent<HTMLElement>,
    key: HudPositionKey,
  ) => {
    if (isPlaying || !stageRef.current) return;
    event.stopPropagation();
    didDragRef.current = false;
    const widget =
      key === "hudNeedsPosition"
        ? "needs"
        : key === "hudSkillsPosition"
          ? "skills"
          : "buttons";
    setSelectedHudWidget(widget);
    if (!isHudPlacementMode) {
      return;
    }
    const stageRect = stageRef.current.getBoundingClientRect();
    const widgetRect = event.currentTarget.getBoundingClientRect();
    const scaleX = logicalStageWidth / stageRect.width;
    const scaleY = logicalStageHeight / stageRect.height;
    const widgetX = (widgetRect.left - stageRect.left) * scaleX;
    const widgetY = (widgetRect.top - stageRect.top) * scaleY;
    const widgetWidth = widgetRect.width * scaleX;
    const widgetHeight = widgetRect.height * scaleY;
    setDraggingHudWidget({
      key,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      startX: widgetX,
      startY: widgetY,
      width: widgetWidth,
      height: widgetHeight,
    });
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const handleHudWidgetPointerMove = (
    event: React.PointerEvent<HTMLElement>,
  ) => {
    if (
      !draggingHudWidget ||
      draggingHudWidget.pointerId !== event.pointerId ||
      !stageRef.current
    ) {
      return;
    }
    event.stopPropagation();
    didDragRef.current = true;
    const stageRect = stageRef.current.getBoundingClientRect();
    const scaleX = logicalStageWidth / stageRect.width;
    const scaleY = logicalStageHeight / stageRect.height;
    const x =
      draggingHudWidget.startX +
      (event.clientX - draggingHudWidget.startClientX) * scaleX;
    const y =
      draggingHudWidget.startY +
      (event.clientY - draggingHudWidget.startClientY) * scaleY;
    const clampedX = Math.max(
      0,
      Math.min(logicalStageWidth - draggingHudWidget.width, x),
    );
    const clampedY = Math.max(
      0,
      Math.min(logicalStageHeight - draggingHudWidget.height, y),
    );
    setProject((current) => ({
      ...current,
      globalSettings: {
        ...current.globalSettings,
        [draggingHudWidget.key]: {
          x: Math.round(clampedX),
          y: Math.round(clampedY),
        },
      },
    }));
  };

  const handleHudWidgetPointerUp = (
    event: React.PointerEvent<HTMLElement>,
  ) => {
    if (
      !draggingHudWidget ||
      draggingHudWidget.pointerId !== event.pointerId
    ) {
      return;
    }
    event.stopPropagation();
    try {
      event.currentTarget.releasePointerCapture(event.pointerId);
    } catch (error) {}
    setDraggingHudWidget(null);
  };

  const handleHudResizePointerDown = (
    event: React.PointerEvent<HTMLElement>,
    widget: HudWidgetId,
    axis: "x" | "y" | "xy",
    scaleX: number,
    scaleY: number,
  ) => {
    if (isPlaying) return;
    event.preventDefault();
    event.stopPropagation();
    const widgetElement = event.currentTarget.parentElement;
    if (!widgetElement) return;
    const bounds = widgetElement.getBoundingClientRect();
    setSelectedHudWidget(widget);
    const resizeState: HudResizeState = {
      widget,
      pointerId: event.pointerId,
      axis,
      startX: event.clientX,
      startY: event.clientY,
      startScaleX: scaleX,
      startScaleY: scaleY,
      renderedWidth: Math.max(1, bounds.width),
      renderedHeight: Math.max(1, bounds.height),
    };
    resizingHudWidgetRef.current = resizeState;
    const config = getHudWidgetConfig(widget);
    const handleWindowPointerMove = (moveEvent: PointerEvent) => {
      if (moveEvent.pointerId !== resizeState.pointerId) return;
      const deltaX = moveEvent.clientX - resizeState.startX;
      const deltaY = moveEvent.clientY - resizeState.startY;
      const baseWidth = resizeState.renderedWidth / resizeState.startScaleX;
      const baseHeight = resizeState.renderedHeight / resizeState.startScaleY;
      const nextScaleX =
        resizeState.axis === "y"
          ? resizeState.startScaleX
          : Math.max(
              0.1,
              Math.min(4, resizeState.startScaleX + deltaX / baseWidth),
            );
      const nextScaleY =
        resizeState.axis === "x"
          ? resizeState.startScaleY
          : Math.max(
              0.1,
              Math.min(4, resizeState.startScaleY + deltaY / baseHeight),
            );
      setProject((current) => ({
        ...current,
        globalSettings: {
          ...current.globalSettings,
          [config.scaleXKey]: nextScaleX,
          [config.scaleYKey]: nextScaleY,
        },
      }));
    };
    const handleWindowPointerUp = (upEvent: PointerEvent) => {
      if (upEvent.pointerId !== resizeState.pointerId) return;
      window.removeEventListener("pointermove", handleWindowPointerMove);
      window.removeEventListener("pointerup", handleWindowPointerUp);
      window.removeEventListener("pointercancel", handleWindowPointerUp);
      resizingHudWidgetRef.current = null;
    };
    window.addEventListener("pointermove", handleWindowPointerMove);
    window.addEventListener("pointerup", handleWindowPointerUp);
    window.addEventListener("pointercancel", handleWindowPointerUp);
  };

  const renderHudResizeHandles = (
    widget: HudWidgetId,
    scaleX: number,
    scaleY: number,
  ) => {
    if (isPlaying || !isHudPlacementMode || selectedHudWidget !== widget) return null;
    const handleClass =
      "absolute z-[2100] border-2 border-neutral-950 bg-pink-300 shadow-[0_0_0_1px_white]";
    return (
      <>
        <button
          type="button"
          aria-label={`Resize ${getHudWidgetConfig(widget).label} width`}
          className={`${handleClass} -right-2 top-1/2 h-8 w-4 -translate-y-1/2 cursor-ew-resize rounded-sm`}
          onPointerDown={(event) =>
            handleHudResizePointerDown(event, widget, "x", scaleX, scaleY)
          }
        />
        <button
          type="button"
          aria-label={`Resize ${getHudWidgetConfig(widget).label} height`}
          className={`${handleClass} -bottom-2 left-1/2 h-4 w-8 -translate-x-1/2 cursor-ns-resize rounded-sm`}
          onPointerDown={(event) =>
            handleHudResizePointerDown(event, widget, "y", scaleX, scaleY)
          }
        />
        <button
          type="button"
          aria-label={`Resize ${getHudWidgetConfig(widget).label} freely`}
          className={`${handleClass} -bottom-3 -right-3 flex h-6 w-6 cursor-nwse-resize items-center justify-center rounded-md text-[11px] font-black text-neutral-950`}
          onPointerDown={(event) =>
            handleHudResizePointerDown(event, widget, "xy", scaleX, scaleY)
          }
        >
          ↘
        </button>
      </>
    );
  };

  const getWorkingScene = () => {
    if (editorMode === "ui_stage" && !isPlaying) {
      return (
        (project.uiMenus || []).find((s) => s.id === project.currentUiMenuId) ||
        (project.uiMenus || [])[0] ||
        null
      );
    }
    return (
      project.scenes.find((s) => s.id === project.currentSceneId) ||
      project.scenes[0] ||
      null
    );
  };
  const currentScene = getWorkingScene() || {
    id: "fallback",
    name: "Fallback",
    width: 800,
    height: 600,
    backgroundColor: "#000",
    objects: [],
  };
  const selectedObject = currentScene?.objects.find(
    (o) => o.id === selectedObjectId,
  );
  const hasPlayableCursorAsset = (assetId?: string | null) =>
    Boolean(
      assetId &&
        project.assets.some(
          (asset) => asset.id === assetId && getAssetDisplaySrc(asset),
        ),
    );
  const activeCursorAssetId =
    hoverCursorAssetId || project.globalSettings.customCursorAssetId || null;
  const activeCursorAsset = activeCursorAssetId
    ? project.assets.find(
        (asset) => asset.id === activeCursorAssetId && getAssetDisplaySrc(asset),
      )
    : undefined;
  const getObjectMediaSrc = (object: SceneObject) => {
    const linkedAsset = object._assetId
      ? project.assets.find((asset) => asset.id === object._assetId)
      : undefined;
    return (
      getAssetDisplaySrc(linkedAsset) ||
      inferGitHubAssetIdSrc(object._assetId) ||
      object.src ||
      ""
    );
  };
  const renderObjectMedia = (
    object: SceneObject,
    className?: string,
  ) => {
    const mediaSrc = getObjectMediaSrc(object);
    if (!mediaSrc) return null;
    const objectFitClass =
      object.objectFit === "contain"
        ? "object-contain"
        : object.objectFit === "cover"
          ? "object-cover"
          : "object-fill";
    const mediaClassName =
      className || `w-full h-full pointer-events-none ${objectFitClass}`;
    const transform = `scaleX(${object.flipX ? -1 : 1}) scaleY(${
      object.flipY ? -1 : 1
    })`;
    return object.isVideo ? (
      <video
        src={mediaSrc}
        className={mediaClassName}
        autoPlay
        loop
        muted={!isPlaying}
        playsInline
        style={{ transform }}
      />
    ) : (
      <img
        src={mediaSrc}
        alt=""
        className={mediaClassName}
        draggable={false}
        style={{ transform }}
      />
    );
  };

  const getInventoryIconSrc = (itemId: string) => {
    const item = project.inventoryItems.find((candidate) => candidate.id === itemId);
    if (!item?.iconAssetId) return "";
    const asset = project.assets.find((candidate) => candidate.id === item.iconAssetId);
    return getAssetDisplaySrc(asset) || inferGitHubAssetIdSrc(item.iconAssetId) || "";
  };

  const getVisibleLoreEntries = (source?: SceneObject["uiTextSource"]) => {
    const entries = project.loreEntries || [];
    return entries.filter((entry) => {
      if (entry.requiredFlagId && !playerFlags.includes(entry.requiredFlagId)) return false;
      if (source === "journal") return entry.entryType === "journal";
      if (source === "quest_note") return entry.entryType === "quest_note";
      if (source === "lore") return entry.entryType === "lore";
      return true;
    });
  };

  const handleInventoryItemClickInPlay = (itemId: string) => {
    const item = project.inventoryItems.find((candidate) => candidate.id === itemId);
    if (!item) return;

    if (selectedInventoryItemId === itemId) {
      setSelectedInventoryItemId(null);
      if (isInventoryOpen) setIsInventoryOpen(false);
      setPreviewDialogue(
        item.description
          ? `(Item): ${item.description}`
          : `You look at: ${item.name}.`,
      );
      return;
    }

    if (selectedInventoryItemId && selectedInventoryItemId !== itemId) {
      const combination = (project.craftingRecipes || []).find((recipe) =>
        recipeMatchesSelection(recipe, [selectedInventoryItemId, itemId]),
      );

      if (combination) {
        setPlayerInventory((prev) =>
          applyCraftingRecipeToInventory(prev, combination),
        );
        applyCraftingOutcomes(combination);
        setSelectedInventoryItemId(null);
        setPreviewDialogue(
          combination.successMessage || "Items combined successfully!",
        );
      } else {
        setPreviewDialogue("These objects do not combine.");
        setSelectedInventoryItemId(null);
      }
      return;
    }

    setSelectedInventoryItemId(itemId);
  };

  const renderSmartUiRegion = (obj: SceneObject) => {
    const primary = obj.uiColorPrimary || project.globalSettings.uiColorPrimary || "#00ffcc";
    const secondary = obj.uiColorSecondary || "rgba(0,0,0,0.68)";
    const padding = obj.uiPadding ?? 10;
    const isEditor = !isPlaying;
    const border =
      obj.uiBorderType === "none"
        ? "none"
        : `2px ${obj.uiBorderType === "solid" ? "solid" : "dashed"} ${primary}`;
    const slotChrome =
      obj.uiBorderType === "none"
        ? { backgroundColor: "transparent", borderColor: "transparent" }
        : undefined;

    if (isEditor) {
      const columns = Math.max(1, obj.uiGridColumns || 4);
      const rows = Math.max(1, obj.uiGridRows || 3);
      const label =
        obj.uiElementType === "inventory_grid"
          ? "LIVE ITEM SLOTS"
          : obj.uiElementType === "journal_text"
            ? "LIVE JOURNAL TEXT"
            : obj.uiElementType === "quest_list"
              ? "LIVE QUEST LIST"
              : obj.uiElementType === "stat_list"
                ? "LIVE STATS"
                : "LIVE REGION";

      return (
        <div
          className="h-full w-full overflow-hidden"
          style={{
            border: `2px dashed ${primary}`,
            backgroundColor: "rgba(4,12,22,0.14)",
            color: primary,
            boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.08)",
          }}
        >
          <div className="pointer-events-none absolute left-1 top-1 z-10 rounded border border-black/60 bg-black/80 px-1.5 py-0.5 font-mono text-[9px] font-bold leading-none text-cyan-100 shadow">
            {label}
          </div>
          {obj.uiElementType === "inventory_grid" ? (
            <div
              className="absolute inset-2 grid"
              style={{
                paddingTop: 14,
                gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
                gap: Math.max(2, Math.min(8, obj.uiGridGap ?? 4)),
              }}
            >
              {Array.from({ length: columns * rows }).map((_, index) => (
                <div
                  key={index}
                  className="rounded-[2px] border border-cyan-200/45 bg-cyan-200/5"
                />
              ))}
            </div>
          ) : (
            <div className="pointer-events-none flex h-full w-full items-center justify-center px-3 pt-5 text-center font-mono text-[10px] font-bold uppercase tracking-wide text-cyan-100/80">
              Resize over the matching panel
            </div>
          )}
        </div>
      );
    }

    if (obj.uiElementType === "inventory_grid") {
      const columns = Math.max(1, obj.uiGridColumns || 4);
      const rows = Math.max(1, obj.uiGridRows || 3);
      const gap = obj.uiGridGap ?? 8;
      const visibleIds = isEditor
        ? (playerInventory.length ? playerInventory : project.inventoryItems.slice(0, columns * rows).map((item) => item.id))
        : playerInventory;
      const cells = Array.from({ length: columns * rows }, (_, index) => visibleIds[index] || "");
      return (
        <div
          className="ui-smart-region ui-smart-region--inventory"
          style={{
            border,
            backgroundColor: secondary,
            padding,
            gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
            gap,
          }}
        >
          {cells.map((itemId, index) => {
            const item = project.inventoryItems.find((candidate) => candidate.id === itemId);
            const iconSrc = itemId ? getInventoryIconSrc(itemId) : "";
            const isSelected = selectedInventoryItemId === itemId;
            return (
              <button
                type="button"
                key={`${itemId || "empty"}-${index}`}
                className={`ui-smart-region__slot ${itemId ? "ui-smart-region__slot--item" : ""} ${isSelected ? "ui-smart-region__slot--selected" : ""}`}
                disabled={!itemId}
                onClick={(event) => {
                  event.stopPropagation();
                  if (itemId) handleInventoryItemClickInPlay(itemId);
                }}
                style={slotChrome}
              >
                {iconSrc ? (
                  <img src={iconSrc} alt="" draggable={false} />
                ) : item ? (
                  <span>{item.name.slice(0, 2)}</span>
                ) : null}
              </button>
            );
          })}
          {!isEditor && playerInventory.length === 0 && (
            <div className="ui-smart-region__empty">{obj.uiEmptyText || "Inventory empty"}</div>
          )}
        </div>
      );
    }

    if (obj.uiElementType === "journal_text") {
      const entries = getVisibleLoreEntries(obj.uiTextSource);
      return (
        <div
          className="ui-smart-region ui-smart-region--text"
          style={{
            border,
            backgroundColor: secondary,
            color: obj.textColor || primary,
            fontFamily: obj.textFontFamily || project.globalSettings.uiFontFamily,
            fontSize: obj.textFontSize || 14,
            lineHeight: obj.textLineHeight || 1.35,
            padding,
          }}
        >
          {entries.length ? (
            entries.slice(0, 6).map((entry) => (
              <article key={entry.id}>
                <strong>{entry.title || "Untitled"}</strong>
                {entry.content && <p>{entry.content}</p>}
              </article>
            ))
          ) : (
            <span>{obj.uiEmptyText || (isEditor ? "Journal text fills this box" : "No journal entries yet.")}</span>
          )}
        </div>
      );
    }

    if (obj.uiElementType === "quest_list") {
      const quests = project.quests.filter(
        (quest) =>
          activeQuests.includes(quest.id) ||
          completedQuests.includes(quest.id) ||
          (isEditor && project.quests.indexOf(quest) < 4),
      );
      return (
        <div
          className="ui-smart-region ui-smart-region--text"
          style={{
            border,
            backgroundColor: secondary,
            color: obj.textColor || primary,
            fontFamily: obj.textFontFamily || project.globalSettings.uiFontFamily,
            fontSize: obj.textFontSize || 13,
            lineHeight: obj.textLineHeight || 1.25,
            padding,
          }}
        >
          {quests.length ? (
            quests.slice(0, 6).map((quest) => (
              <article key={quest.id}>
                <strong>{quest.name || "Untitled quest"}</strong>
                <p>{completedQuests.includes(quest.id) ? "Complete" : quest.description || "Active objective"}</p>
              </article>
            ))
          ) : (
            <span>{obj.uiEmptyText || (isEditor ? "Quest rows fill this box" : "No active quests.")}</span>
          )}
        </div>
      );
    }

    if (obj.uiElementType === "stat_list") {
      const tracks = Object.entries(playerNeeds);
      const fallbackTracks = ["hunger", "rest", "novelty", "connection"].map((id) => [id, 70] as [string, number]);
      return (
        <div
          className="ui-smart-region ui-smart-region--stats"
          style={{
            border,
            backgroundColor: secondary,
            color: obj.textColor || primary,
            fontFamily: obj.textFontFamily || project.globalSettings.uiFontFamily,
            fontSize: obj.textFontSize || 12,
            padding,
          }}
        >
          {(tracks.length ? tracks : fallbackTracks).slice(0, 8).map(([label, value]) => (
            <div key={label} className="ui-smart-region__meter">
              <span>{label}</span>
              <i>
                <b style={{ width: `${Math.max(0, Math.min(100, Number(value) || 0))}%`, backgroundColor: primary }} />
              </i>
            </div>
          ))}
        </div>
      );
    }

    return null;
  };

  const updateScene = (updates: Partial<typeof currentScene>) => {
    if (!currentScene) return;
    const isUI = editorMode === "ui_stage" && !isPlaying;
    const newProject = {
      ...project,
      [isUI ? "uiMenus" : "scenes"]: (
        project[isUI ? "uiMenus" : "scenes"] || []
      ).map((s) => (s.id === currentScene.id ? { ...s, ...updates } : s)),
    };
    pushHistory(newProject);
  };

  const updateObject = (id: string, updates: Partial<SceneObject>) => {
    if (!currentScene) return;
    const isUI = editorMode === "ui_stage" && !isPlaying;
    const newProject = {
      ...project,
      [isUI ? "uiMenus" : "scenes"]: (
        project[isUI ? "uiMenus" : "scenes"] || []
      ).map((s) =>
        s.id === currentScene.id
          ? {
              ...s,
              objects: s.objects.map((o) =>
                o.id === id ? { ...o, ...updates } : o,
              ),
            }
          : s,
      ),
    };
    pushHistory(newProject);
  };

  const updateObjectTransient = (id: string, updates: Partial<SceneObject>) => {
    if (!currentScene) return;
    const isUI = editorMode === "ui_stage" && !isPlaying;
    setProject((prev) => ({
      ...prev,
      [isUI ? "uiMenus" : "scenes"]: (
        prev[isUI ? "uiMenus" : "scenes"] || []
      ).map((s) =>
        s.id === currentScene.id
          ? {
              ...s,
              objects: s.objects.map((o) =>
                o.id === id ? { ...o, ...updates } : o,
              ),
            }
          : s,
      ),
    }));
  };

  const handleInsertAssetToStage = (asset: any) => {
    if (isPlaying) return;

    const isUI = editorMode === "ui_stage" && !isPlaying;
    const targetCollection = isUI ? "uiMenus" : "scenes";
    const targetId = isUI ? project.currentUiMenuId : project.currentSceneId;
    const targetScene =
      (project[targetCollection] || []).find((scene) => scene.id === targetId) ||
      (project[targetCollection] || [])[0];

    if (!targetScene) {
      showError("Open or create a room first, then place the asset.");
      return;
    }

    let objDefaults: Partial<SceneObject> = {};
    if (asset.type === "custom_prefab") {
       const newObj = { ...asset.prefabData, id: uuidv4(), x: 0, y: 0 };
       const newProject = {
          ...project,
          [targetCollection]: (project[targetCollection] || []).map((s) =>
            s.id === targetScene.id
              ? { ...s, objects: [...s.objects, newObj] }
              : s,
          ),
       };
       pushHistory(newProject);
       setSelectedObjectId(newObj.id);
       showError(`${asset.name || "Prefab"} placed in ${targetScene.name}.`);
       return;
    } else if (asset.type === "prefab") {
      if (asset.prefabType === "chest") {
        objDefaults = {
          isText: true,
          textContent: "🎁",
          textFontSize: 64,
          width: 64,
          height: 64,
          interaction: "give-item",
          name: "Loot Chest",
        };
      } else if (asset.prefabType === "door") {
        objDefaults = {
          isHitbox: true,
          width: 64,
          height: 128,
          interaction: "scene_change",
          name: "Portal / Door",
        };
      } else if (asset.prefabType === "npc") {
        objDefaults = {
          isHitbox: true,
          width: 100,
          height: 100,
          interaction: "dialogue",
          name: "NPC Trigger",
        };
      }
    }

    let actualSrc = getAssetDisplaySrc(asset);
    if (asset.id && !actualSrc) {
      const matchedAsset = project.assets.find((a: any) => a.id === asset.id);
      if (matchedAsset) actualSrc = getAssetDisplaySrc(matchedAsset);
    }

    const currentArr = targetScene.objects || [];
    const shouldUseImageAsUiPageBacking =
      isUI &&
      asset.type === "image" &&
      currentArr.length === 0;
    const targetSceneWidth =
      targetScene.width || project.globalSettings.stageWidth || 800;
    const targetSceneHeight =
      targetScene.height || project.globalSettings.stageHeight || 600;
    const imagePlacement = getAssetPlacementSize(asset);

    const newObj: SceneObject = {
      id: uuidv4(),
      name:
        shouldUseImageAsUiPageBacking
          ? `${asset.name} Page Art`
          : asset.type === "audio"
          ? `Sound cue: ${asset.name}`
          : asset.type === "video"
            ? `Video cue: ${asset.name}`
            : asset.type === "script"
              ? `Script cue: ${asset.name}`
              : asset.name,
      src: actualSrc,
      _assetId: asset.id,
      x: shouldUseImageAsUiPageBacking ? 0 : targetSceneWidth / 2 - 50,
      y: shouldUseImageAsUiPageBacking ? 0 : targetSceneHeight / 2 - 50,
      width:
        shouldUseImageAsUiPageBacking
          ? targetSceneWidth
          : asset.type === "ui_element"
          ? asset.uiElementType === "panel"
            ? 200
            : asset.uiElementType === "progress"
              ? 150
              : 50
          : asset.type === "hitbox"
            ? 100
            : asset.type === "audio"
              ? 160
              : asset.type === "video"
                ? 180
            : asset.type === "script"
              ? 64
              : asset.type === "text"
                ? 200
                : asset.type === "image"
                  ? imagePlacement.width
                : 100,
      height:
        shouldUseImageAsUiPageBacking
          ? targetSceneHeight
          : asset.type === "ui_element"
          ? asset.uiElementType === "panel"
            ? 200
            : asset.uiElementType === "progress"
              ? 20
              : 50
          : asset.type === "hitbox"
            ? 100
            : asset.type === "audio"
              ? 56
              : asset.type === "video"
                ? 100
            : asset.type === "script"
              ? 64
              : asset.type === "text"
                ? 50
                : asset.type === "image"
                  ? imagePlacement.height
                : 100,
      rotation: 0,
      zIndex:
        shouldUseImageAsUiPageBacking
          ? 0
          : currentArr.length > 0
          ? Math.max(...currentArr.map((o) => o.zIndex)) + 1
          : 0,
      opacity: 1,
      locked: shouldUseImageAsUiPageBacking,
      cursor:
        asset.type === "prefab" || asset.type === "audio"
          ? "pointer"
          : "default",
      animation: "none",
      interaction:
        asset.type === "audio"
          ? "sound"
          : asset.type === "video"
            ? "play_cutscene"
            : "none",
      interactionData:
        asset.type === "audio" || asset.type === "video" ? asset.id : undefined,
      isVideo: asset.type === "video",
      isHitbox: asset.type === "hitbox",
      isScript: asset.type === "script",
      isText: asset.type === "text" || asset.type === "audio" || asset.type === "script",
      isUiElement: asset.type === "ui_element",
      uiElementType: asset.uiElementType,
      uiColorPrimary: "#00ffff",
      uiColorSecondary: "#ff00ff",
      uiIconType: "check",
      uiValue: 50,
      uiChecked: true,
      uiBorderType: "solid",
      textContent:
        asset.type === "text"
          ? "New Text"
          : asset.type === "audio"
            ? `♪ Sound cue`
            : asset.type === "script"
              ? "{ } Script"
            : asset.type === "ui_element" && asset.uiElementType === "tooltip"
              ? "Tooltip text"
              : undefined,
      textColor: "#ffffff",
      textFontSize: 24,
      textFontFamily: "sans-serif",
      blendMode: "normal",
      parallaxSpeed: 1,
      hasPhysics: false,
      ignoreClicks: shouldUseImageAsUiPageBacking,
      stretchToScreen: shouldUseImageAsUiPageBacking,
      objectFit: shouldUseImageAsUiPageBacking ? "contain" : undefined,
      scriptAssetId: asset.type === "script" ? asset.id : undefined,
      ...objDefaults,
    };

    const newProject = {
      ...project,
      [targetCollection]: (project[targetCollection] || []).map((scene) =>
        scene.id === targetScene.id
          ? { ...scene, objects: [...currentArr, newObj] }
          : scene,
      ),
    };
    pushHistory(newProject);
    setSelectedObjectId(newObj.id);
    showError(
      shouldUseImageAsUiPageBacking
        ? `${asset.name || "Graphic"} is now the locked page art. Add live zones over its empty panels.`
        : `${asset.name || "Asset"} placed in ${targetScene.name}.`,
    );
  };

  const handleDragStartAsset = (e: React.DragEvent, asset: any) => {
    // Omitting extremely large Data URL (base64) strings from the drag payload prevents crashing Chrome/Firefox
    // We will retrieve the src later by using the asset.id from the project.assets list
    const transferPayload = {
      ...asset,
      src: asset.id ? undefined : getAssetDisplaySrc(asset),
    };
    e.dataTransfer.setData("application/json", JSON.stringify(transferPayload));
  };

  const getDescendantIds = (
    parentIds: string[],
    objects: SceneObject[],
  ): string[] => {
    let ids: string[] = [];
    const children = objects.filter(
      (o) => o.parentObjectId && parentIds.includes(o.parentObjectId),
    );
    if (children.length > 0) {
      const childIds = children.map((c) => c.id);
      ids = childIds.concat(getDescendantIds(childIds, objects));
    }
    return ids;
  };

  const readDroppedFile = (
    file: File,
  ): Promise<{
    asset: Asset;
    width: number;
    height: number;
  } | null> =>
    new Promise((resolve) => {
      const extension = file.name.split(".").pop()?.toLowerCase() || "";
      const isImage =
        file.type.startsWith("image/") ||
        ["png", "jpg", "jpeg", "gif", "webp", "svg"].includes(extension);
      const isAudio =
        file.type.startsWith("audio/") ||
        ["mp3", "wav", "ogg", "m4a", "aac"].includes(extension);
      const isVideo =
        file.type.startsWith("video/") ||
        ["mp4", "webm", "mov"].includes(extension);

      if (!isImage && !isAudio && !isVideo) {
        resolve(null);
        return;
      }

      const maxSize = 5 * 1024 * 1024;
      if (file.size > maxSize) {
        showError(`${file.name} is larger than 5MB and was skipped.`);
        resolve(null);
        return;
      }

      const reader = new FileReader();
      reader.onerror = () => resolve(null);
      reader.onload = () => {
        const src = reader.result as string;
          const asset: Asset = {
            id: uuidv4(),
            name: file.name,
            src,
            width: undefined,
            height: undefined,
            type: isAudio ? "audio" : isVideo ? "video" : "image",
          category: isAudio
            ? "finder/audio"
            : isVideo
              ? "finder/video"
              : "finder/images",
        };

        if (!isImage) {
          resolve({
            asset,
            width: isAudio ? 72 : 320,
            height: isAudio ? 72 : 180,
          });
          return;
        }

        const image = new Image();
        image.onload = () => {
          const maxDimension = 320;
          const scale = Math.min(
            1,
            maxDimension / Math.max(image.naturalWidth, image.naturalHeight),
          );
          resolve({
            asset: {
              ...asset,
              width: image.naturalWidth,
              height: image.naturalHeight,
            },
            width: Math.max(24, Math.round(image.naturalWidth * scale)),
            height: Math.max(24, Math.round(image.naturalHeight * scale)),
          });
        };
        image.onerror = () => resolve({ asset, width: 160, height: 160 });
        image.src = src;
      };
      reader.readAsDataURL(file);
    });

  const importFilesToLibrary = async (files: File[]) => {
    const imported = (await Promise.all(files.map(readDroppedFile))).filter(
      (
        result,
      ): result is { asset: Asset; width: number; height: number } =>
        result !== null,
    );
    if (!imported.length) {
      showError("Choose images, GIFs, audio, or video files.");
      return;
    }
    setProject((current) => ({
      ...current,
      assets: [
        ...imported.map((result) => result.asset),
        ...current.assets,
      ],
    }));
    setLibraryPaletteTab("assets");
    setIsLibraryPaletteOpen(true);
    showError(
      `${imported.length} file${imported.length === 1 ? "" : "s"} added to your collection ✦`,
    );
  };

  const handleDropOnStage = async (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsFinderDragOverStage(false);
    if (!stageRef.current || isPlaying) return;

    const rect = stageRef.current.getBoundingClientRect();
    const stageWidth =
      currentScene.width || project.globalSettings.stageWidth || 800;
    const stageHeight =
      currentScene.height || project.globalSettings.stageHeight || 600;
    const x = ((e.clientX - rect.left) / rect.width) * stageWidth;
    const y = ((e.clientY - rect.top) / rect.height) * stageHeight;

    try {
      const finderFiles = Array.from(e.dataTransfer.files || []);
      if (finderFiles.length > 0) {
        const imported = (
          await Promise.all(finderFiles.map(readDroppedFile))
        ).filter(
          (
            result,
          ): result is { asset: Asset; width: number; height: number } =>
            result !== null,
        );

        if (imported.length === 0) {
          showError("Drop images, GIFs, audio, or video files onto the canvas.");
          return;
        }

        const isUI = editorMode === "ui_stage";
        const targetCollection = isUI ? "uiMenus" : "scenes";
        const targetId = isUI
          ? project.currentUiMenuId
          : project.currentSceneId;
        const targetScene = (project[targetCollection] || []).find(
          (scene) => scene.id === targetId,
        );
        if (!targetScene) return;

        const initialZ =
          targetScene.objects.length > 0
            ? Math.max(...targetScene.objects.map((object) => object.zIndex)) +
              1
            : 0;
        const newObjects: SceneObject[] = imported.map(
          ({ asset, width, height }, index) => ({
            id: uuidv4(),
            name: asset.name,
            src: getAssetDisplaySrc(asset),
            _assetId: asset.id,
            x: Math.max(0, x - width / 2 + index * 22),
            y: Math.max(0, y - height / 2 + index * 22),
            width,
            height,
            rotation: 0,
            zIndex: initialZ + index,
            opacity: 1,
            locked: false,
            cursor: asset.type === "audio" ? "pointer" : "default",
            animation: "none",
            interaction:
              asset.type === "audio"
                ? "sound"
                : asset.type === "video"
                  ? "play_cutscene"
                  : "none",
            interactionData:
              asset.type === "audio" || asset.type === "video"
                ? asset.id
                : undefined,
            isVideo: asset.type === "video",
            isHitbox: false,
            isScript: false,
            isText: asset.type === "audio",
            isUiElement: false,
            textContent: asset.type === "audio" ? "🎵" : undefined,
            textColor: "#ffffff",
            textFontSize: 32,
            textFontFamily: "sans-serif",
            blendMode: "normal",
            parallaxSpeed: 1,
            hasPhysics: false,
          }),
        );

        const newProject = {
          ...project,
          assets: [...imported.map((result) => result.asset), ...project.assets],
          [targetCollection]: (project[targetCollection] || []).map((scene) =>
            scene.id === targetId
              ? { ...scene, objects: [...scene.objects, ...newObjects] }
              : scene,
          ),
        };
        pushHistory(newProject);
        setSelectedObjectId(newObjects[newObjects.length - 1].id);
        showError(
          `${newObjects.length} file${newObjects.length === 1 ? "" : "s"} imported from Finder ✦`,
        );
        return;
      }

      const assetData = e.dataTransfer.getData("application/json");
      if (assetData) {
        const asset = JSON.parse(assetData);

        let objDefaults: Partial<SceneObject> = {};
        if (asset.type === "custom_prefab") {
           const newObj = { ...asset.prefabData, id: uuidv4(), x, y };
           const isUI = editorMode === "ui_stage";
           const newProject = {
              ...project,
              [isUI ? "uiMenus" : "scenes"]: (project[isUI ? "uiMenus" : "scenes"] || []).map((s) => s.id === currentScene.id ? { ...s, objects: [...s.objects, newObj] } : s)
           };
           setProject(newProject);
           pushHistory(newProject);
           setSelectedObjectId(newObj.id);
           return;
        } else if (asset.type === "prefab") {
          if (asset.prefabType === "chest") {
            objDefaults = {
              isText: true,
              textContent: "🎁",
              textFontSize: 64,
              width: 64,
              height: 64,
              interaction: "give-item",
              name: "Loot Chest",
            };
            // Optional: automatically ask user what item? We can just leave it blank for now.
            showError(
              'Loot Chest dropped! Remember to select it and assign the "Item to Give" in the Interaction settings.',
            );
          } else if (asset.prefabType === "door") {
            objDefaults = {
              isHitbox: true,
              width: 64,
              height: 128,
              interaction: "scene_change",
              name: "Portal / Door",
            };
            showError(
              'Portal dropped! Select it and assign the "Portal Destination" in the property panel.',
            );
          } else if (asset.prefabType === "npc") {
            objDefaults = {
              isHitbox: true,
              width: 100,
              height: 100,
              interaction: "dialogue",
              name: "NPC Trigger",
            };
            showError(
              'NPC dropped! Select it and assign a "Conversation" in the Interaction settings.',
            );
          }
        }

        let actualSrc = getAssetDisplaySrc(asset);
        if (asset.id && !actualSrc) {
          const matchedAsset = project.assets.find(
            (a: any) => a.id === asset.id,
          );
          if (matchedAsset) actualSrc = getAssetDisplaySrc(matchedAsset);
        }

        const newObj: SceneObject = {
          id: uuidv4(),
          name:
            asset.type === "audio"
              ? `Sound cue: ${asset.name}`
              : asset.type === "video"
                ? `Video cue: ${asset.name}`
                : asset.type === "script"
                  ? `Script cue: ${asset.name}`
                  : asset.name,
          src: actualSrc,
          _assetId: asset.id,
          x: x - 50, // Center roughly
          y: y - 50,
          width:
            asset.type === "ui_element"
              ? asset.uiElementType === "panel"
                ? 200
                : asset.uiElementType === "progress"
                  ? 150
                  : 50
              : asset.type === "hitbox"
                ? 100
                : asset.type === "audio"
                  ? 160
                  : asset.type === "video"
                    ? 180
                : asset.type === "script"
                  ? 64
                  : asset.type === "text"
                    ? 200
                    : 100,
          height:
            asset.type === "ui_element"
              ? asset.uiElementType === "panel"
                ? 200
                : asset.uiElementType === "progress"
                  ? 20
                  : 50
              : asset.type === "hitbox"
                ? 100
                : asset.type === "audio"
                  ? 56
                  : asset.type === "video"
                    ? 100
                : asset.type === "script"
                  ? 64
                  : asset.type === "text"
                    ? 50
                    : 100,
          rotation: 0,
          zIndex:
            (currentScene?.objects.length ?? 0) > 0
              ? Math.max(...currentScene!.objects.map((o) => o.zIndex)) + 1
              : 0,
          opacity: 1,
          locked: false,
          cursor:
            asset.type === "prefab" || asset.type === "audio"
              ? "pointer"
              : "default",
          animation: "none",
          interaction: asset.type === "audio" ? "sound" : "none",
          interactionData: asset.type === "audio" ? asset.id : undefined,
          isVideo: asset.type === "video",
          isHitbox: asset.type === "hitbox",
          isScript: asset.type === "script",
          isText: asset.type === "text" || asset.type === "audio" || asset.type === "script",
          isUiElement: asset.type === "ui_element",
          uiElementType: asset.uiElementType,
          uiColorPrimary: "#00ffff",
          uiColorSecondary: "#ff00ff",
          uiIconType: "check",
          uiValue: 50,
          uiChecked: true,
          uiBorderType: "solid",
          textContent:
            asset.type === "text"
              ? "New Text"
              : asset.type === "audio"
                ? "♪ Sound cue"
                : asset.type === "script"
                  ? "{ } Script"
                : asset.type === "ui_element" &&
                    asset.uiElementType === "tooltip"
                  ? "Tooltip text"
                  : undefined,
          textColor: "#ffffff",
          textFontSize: 24,
          textFontFamily: "sans-serif",
          blendMode: "normal",
          parallaxSpeed: 1,
          hasPhysics: false,
          scriptAssetId: asset.type === "script" ? asset.id : undefined,
          ...objDefaults,
        };

        updateScene({ objects: [...currentScene.objects, newObj] });
        setSelectedObjectId(newObj.id);
      }
    } catch (err) {
      console.error("Drop error", err);
    }
  };

  const handleStageDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (isPlaying) return;
    e.dataTransfer.dropEffect =
      e.dataTransfer.types.includes("Files") ? "copy" : "move";
    if (e.dataTransfer.types.includes("Files")) {
      setIsFinderDragOverStage(true);
    }
  };

  // Resizing state
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [resizeStart, setResizeStart] = useState({
    w: 0,
    h: 0,
    x: 0,
    y: 0,
    objX: 0,
    objY: 0,
    anchor: "se",
    preserveAspect: false,
    aspect: 1,
  });

  const [rotatingId, setRotatingId] = useState<string | null>(null);
  const [rotateStart, setRotateStart] = useState({
    r: 0,
    cx: 0,
    cy: 0,
    startAngle: 0,
  });

  // Object dragging on stage
  const handleObjectPointerDown = (e: React.PointerEvent, obj: SceneObject) => {
    if (isPlaying) {
      if (!obj.isDraggable) return;
      e.preventDefault();
      e.stopPropagation();
      runtimeDraggingIdRef.current = obj.id;
      setRuntimeDraggingId(obj.id);

      const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
      const offset = {
        x: ((e.clientX - rect.left) / rect.width) * obj.width,
        y: ((e.clientY - rect.top) / rect.height) * obj.height,
      };
      dragOffsetRef.current = offset;
      setDragOffset(offset);

      try {
        (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
      } catch (err) {}
      return;
    }
    if (obj.locked) return;
    e.preventDefault();
    e.stopPropagation();
    if (rightSidebarWidth === 0) setRightSidebarWidth(320);
    setSelectedHudWidget(null);

    if (e.shiftKey) {
      if (selectedMultiIds.includes(obj.id)) {
        setSelectedMultiIds((prev) => prev.filter((id) => id !== obj.id));
        setSelectedObjectId((prev) => (prev === obj.id ? null : prev));
      } else {
        if (!selectedMultiIds.includes(selectedObjectId || "")) {
          setSelectedMultiIds(
            selectedObjectId ? [selectedObjectId, obj.id] : [obj.id],
          );
        } else {
          setSelectedMultiIds((prev) => [...prev, obj.id]);
        }
        setSelectedObjectId(obj.id);
      }
    } else {
      // If we click an object already in multi-selection, don't clear.
      // This allows dragging the whole group.
      if (!selectedMultiIds.includes(obj.id)) {
        setSelectedObjectId(obj.id);
        setSelectedMultiIds([obj.id]);
      } else {
        setSelectedObjectId(obj.id);
      }
    }

    draggingIdRef.current = obj.id;
    setDraggingId(obj.id);
    dragStartProjectRef.current = project;
    didDragRef.current = false;

    // Calculate offset from top-left of object
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const offset = {
      x: ((e.clientX - rect.left) / rect.width) * obj.width,
      y: ((e.clientY - rect.top) / rect.height) * obj.height,
    };
    dragOffsetRef.current = offset;
    setDragOffset(offset);

    try {
      (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    } catch (err) {}
  };

  const handleResizePointerDown = (
    e: React.PointerEvent,
    obj: SceneObject,
    anchor: string = "se",
  ) => {
    if (isPlaying || obj.locked) return;
    e.stopPropagation();
    setResizingId(obj.id);
    dragStartProjectRef.current = project;
    setResizeStart({
      w: obj.width,
      h: obj.height,
      x: e.clientX,
      y: e.clientY,
      objX: obj.x,
      objY: obj.y,
      anchor,
      preserveAspect: e.shiftKey,
      aspect: obj.height > 0 ? obj.width / obj.height : 1,
    });
    try {
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    } catch (err) {}
  };

  const handleRotatePointerDown = (e: React.PointerEvent, obj: SceneObject) => {
    if (isPlaying || obj.locked) return;
    e.stopPropagation();
    setRotatingId(obj.id);
    dragStartProjectRef.current = project;

    // Find absolute center of the object relative to viewport
    const parentEl = (e.currentTarget as HTMLElement).parentElement;
    if (!parentEl) return;

    const rect = parentEl.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;

    // Calculate initial angle of mouse pointer relative to center
    const startAngle =
      Math.atan2(e.clientY - cy, e.clientX - cx) * (180 / Math.PI);

    setRotateStart({ r: obj.rotation || 0, cx, cy, startAngle });

    try {
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    } catch (err) {}
  };

  const handleObjectPointerMove = (e: React.PointerEvent) => {
    if (isPlaying) {
      const activeRuntimeDraggingId = runtimeDraggingIdRef.current;
      if (activeRuntimeDraggingId && stageRef.current) {
        const rect = stageRef.current.getBoundingClientRect();
        const stageWidth =
          currentScene.width || project.globalSettings.stageWidth || 800;
        const stageHeight =
          currentScene.height || project.globalSettings.stageHeight || 600;
        let newX =
          ((e.clientX - rect.left) / rect.width) * stageWidth -
          dragOffsetRef.current.x;
        let newY =
          ((e.clientY - rect.top) / rect.height) * stageHeight -
          dragOffsetRef.current.y;
        setRuntimeOverrides((prev) => ({
          ...prev,
          [activeRuntimeDraggingId]: { x: newX, y: newY },
        }));
      }

      if (stageRef.current) {
        const rect = stageRef.current.getBoundingClientRect();
        const mx = (e.clientX - rect.left) / rect.width - 0.5;
        const my = (e.clientY - rect.top) / rect.height - 0.5;
        setMouseRatio({ x: mx, y: my });
      }
      return;
    }

    if (resizingId) {
      if (!stageRef.current) return;
      didDragRef.current = true;
      const stageRect = stageRef.current.getBoundingClientRect();
      const stageWidth =
        currentScene.width || project.globalSettings.stageWidth || 800;
      const stageHeight =
        currentScene.height || project.globalSettings.stageHeight || 600;
      const dx =
        (e.clientX - resizeStart.x) * (stageWidth / stageRect.width);
      const dy =
        (e.clientY - resizeStart.y) * (stageHeight / stageRect.height);

      let newW = resizeStart.w;
      let newH = resizeStart.h;
      let newX = resizeStart.objX;
      let newY = resizeStart.objY;

      if (resizeStart.anchor.includes("e"))
        newW = Math.max(10, resizeStart.w + dx);
      if (resizeStart.anchor.includes("w")) {
        newW = Math.max(10, resizeStart.w - dx);
        newX = resizeStart.objX + (resizeStart.w - newW);
      }
      if (resizeStart.anchor.includes("s"))
        newH = Math.max(10, resizeStart.h + dy);
      if (resizeStart.anchor.includes("n")) {
        newH = Math.max(10, resizeStart.h - dy);
        newY = resizeStart.objY + (resizeStart.h - newH);
      }

      if (
        resizeStart.preserveAspect &&
        e.shiftKey &&
        resizeStart.anchor.length === 2
      ) {
        const widthChange = Math.abs(newW - resizeStart.w);
        const heightChange = Math.abs(newH - resizeStart.h);
        if (widthChange >= heightChange * resizeStart.aspect) {
          newH = Math.max(10, newW / resizeStart.aspect);
        } else {
          newW = Math.max(10, newH * resizeStart.aspect);
        }
        if (resizeStart.anchor.includes("w")) {
          newX = resizeStart.objX + (resizeStart.w - newW);
        }
        if (resizeStart.anchor.includes("n")) {
          newY = resizeStart.objY + (resizeStart.h - newH);
        }
      }

      updateObjectTransient(resizingId, {
        width: Math.round(newW),
        height: Math.round(newH),
        x: Math.round(newX),
        y: Math.round(newY),
      });
      return;
    }

    if (rotatingId) {
      didDragRef.current = true;
      const angle =
        Math.atan2(e.clientY - rotateStart.cy, e.clientX - rotateStart.cx) *
        (180 / Math.PI);
      let newRot = rotateStart.r + (angle - rotateStart.startAngle);

      // Snap to 45 deg if shift
      if (e.shiftKey) {
        newRot = Math.round(newRot / 45) * 45;
      }

      updateObjectTransient(rotatingId, { rotation: Math.floor(newRot) % 360 });
      return;
    }

    if (selectionStart && stageRef.current) {
      const rect = stageRef.current.getBoundingClientRect();
      const stageWidth =
        currentScene.width || project.globalSettings.stageWidth || 800;
      const stageHeight =
        currentScene.height || project.globalSettings.stageHeight || 600;
      const mx = ((e.clientX - rect.left) / rect.width) * stageWidth;
      const my = ((e.clientY - rect.top) / rect.height) * stageHeight;
      setSelectionBox({
        x: selectionStart.x,
        y: selectionStart.y,
        w: mx - selectionStart.x,
        h: my - selectionStart.y,
      });
      return;
    }

    const activeDraggingId = draggingIdRef.current || draggingId;
    if (!activeDraggingId || !stageRef.current) return;
    didDragRef.current = true;

    const rect = stageRef.current.getBoundingClientRect();
    const stageWidth =
      currentScene.width || project.globalSettings.stageWidth || 800;
    const stageHeight =
      currentScene.height || project.globalSettings.stageHeight || 600;
    let newX =
      ((e.clientX - rect.left) / rect.width) * stageWidth -
      dragOffsetRef.current.x;
    let newY =
      ((e.clientY - rect.top) / rect.height) * stageHeight -
      dragOffsetRef.current.y;

    // Snap to grid if enabled or shift is held
    if (project.globalSettings.snapToGrid || e.shiftKey) {
      const grid = project.globalSettings.gridSize || 20;
      newX = Math.round(newX / grid) * grid;
      newY = Math.round(newY / grid) * grid;
    }

    if (
      selectedMultiIds.length > 1 &&
      selectedMultiIds.includes(activeDraggingId)
    ) {
      const startSceneList =
        editorMode === "ui_stage"
          ? dragStartProjectRef.current?.uiMenus
          : dragStartProjectRef.current?.scenes;
      const startScene = startSceneList?.find(
        (s: any) =>
          s.id ===
          (editorMode === "ui_stage"
            ? dragStartProjectRef.current?.currentUiMenuId
            : dragStartProjectRef.current?.currentSceneId),
      );
      const startDragObj = startScene?.objects.find(
        (o: any) => o.id === activeDraggingId,
      );

      if (!startDragObj) return;
      const dx = newX - startDragObj.x;
      const dy = newY - startDragObj.y;

      setProject((prev) => {
        const isUI = editorMode === "ui_stage" && !isPlaying;
        const sceneList = isUI ? prev.uiMenus : prev.scenes;
        if (!sceneList) return prev;

        return {
          ...prev,
          [isUI ? "uiMenus" : "scenes"]: sceneList.map((s: any) =>
            s.id === (isUI ? prev.currentUiMenuId : prev.currentSceneId)
              ? {
                  ...s,
                  objects: s.objects.map((o: any) => {
                    const descendantIds = getDescendantIds(
                      selectedMultiIds,
                      s.objects,
                    );
                    if (
                      !selectedMultiIds.includes(o.id) &&
                      !descendantIds.includes(o.id)
                    )
                      return o;
                    const startObj = startScene?.objects.find(
                      (so: any) => so.id === o.id,
                    );
                    if (!startObj) return o;
                    return { ...o, x: startObj.x + dx, y: startObj.y + dy };
                  }),
                }
              : s,
          ),
        };
      });
    } else {
      const startSceneList =
        editorMode === "ui_stage"
          ? dragStartProjectRef.current?.uiMenus
          : dragStartProjectRef.current?.scenes;
      const startScene = startSceneList?.find(
        (s: any) =>
          s.id ===
          (editorMode === "ui_stage"
            ? dragStartProjectRef.current?.currentUiMenuId
            : dragStartProjectRef.current?.currentSceneId),
      );
      const startDragObj = startScene?.objects.find(
        (o: any) => o.id === activeDraggingId,
      );
      if (!startDragObj) return;

      const dx = newX - startDragObj.x;
      const dy = newY - startDragObj.y;

      setProject((prev) => {
        const isUI = editorMode === "ui_stage" && !isPlaying;
        const sceneList = isUI ? prev.uiMenus : prev.scenes;
        if (!sceneList) return prev;

        return {
          ...prev,
          [isUI ? "uiMenus" : "scenes"]: sceneList.map((s: any) =>
            s.id === (isUI ? prev.currentUiMenuId : prev.currentSceneId)
              ? {
                  ...s,
                  objects: s.objects.map((o: any) => {
                    const descendantIds = getDescendantIds(
                      [activeDraggingId],
                      s.objects,
                    );
                    if (
                      o.id !== activeDraggingId &&
                      !descendantIds.includes(o.id)
                    )
                      return o;

                    const startObj = startScene?.objects.find(
                      (so: any) => so.id === o.id,
                    );
                    if (!startObj) return o;
                    return { ...o, x: startObj.x + dx, y: startObj.y + dy };
                  }),
                }
              : s,
          ),
        };
      });
    }
  };

  const handleObjectPointerUp = (e: React.PointerEvent) => {
    if (isPlaying) {
      const activeRuntimeDraggingId =
        runtimeDraggingIdRef.current || runtimeDraggingId;
      if (activeRuntimeDraggingId) {
        runtimeDraggingIdRef.current = null;
        setRuntimeDraggingId(null);
        try {
          (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
        } catch (err) {}
      }
      setSelectionBox(null);
      setSelectionStart(null);
      return;
    }

    if (selectionBox) {
      const bx = Math.min(selectionBox.x, selectionBox.x + selectionBox.w);
      const by = Math.min(selectionBox.y, selectionBox.y + selectionBox.h);
      const bw = Math.abs(selectionBox.w);
      const bh = Math.abs(selectionBox.h);

      const selectedIds = currentScene.objects
        .filter((obj) => {
          return (
            !obj.locked &&
            obj.x < bx + bw &&
            obj.x + obj.width > bx &&
            obj.y < by + bh &&
            obj.y + obj.height > by
          );
        })
        .map((o) => o.id);

      setSelectedMultiIds(selectedIds);
      if (selectedIds.length > 0) setSelectedObjectId(selectedIds[0]);
      else setSelectedObjectId(null);
      setSelectionBox(null);
      setSelectionStart(null);
    }

    const activeDraggingId = draggingIdRef.current || draggingId;
    if (activeDraggingId || resizingId || rotatingId) {
      if (dragStartProjectRef.current) {
        setHistory((h) => ({
          past: [...h.past.slice(-20), dragStartProjectRef.current!],
          future: [],
        }));
      }
    }
    if (activeDraggingId) {
      if (!didDragRef.current && !e.shiftKey) {
        // If they just clicked (no drag) and not holding shift,
        // make sure this object is the only selected one.
        // If holding shift, it stays in the multi-select array (added in pointerdown).
        setSelectedMultiIds([activeDraggingId]);
        setSelectedObjectId(activeDraggingId);
      }
      try {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
      } catch (err) {}
      draggingIdRef.current = null;
      setDraggingId(null);
    }
    if (resizingId) {
      try {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
      } catch (err) {}
      setResizingId(null);
    }
    if (rotatingId) {
      try {
        (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
      } catch (err) {}
      setRotatingId(null);
    }
  };

  // Global keyboard shortcuts for Undo/Redo/Clipboard
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Don't trigger if typing in an input text area
      if (
        document.activeElement?.tagName === "INPUT" ||
        document.activeElement?.tagName === "TEXTAREA"
      )
        return;

      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
        e.preventDefault();
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "y") {
        e.preventDefault();
        redo();
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "a") {
        e.preventDefault();
        setSelectedMultiIds(currentScene.objects.map((o) => o.id));
        setSelectedObjectId(null);
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "c") {
        const idsToCopy =
          selectedMultiIds.length > 0
            ? selectedMultiIds
            : selectedObjectId
              ? [selectedObjectId]
              : [];
        if (idsToCopy.length > 0) {
          e.preventDefault();
          const objs = currentScene.objects.filter((o) =>
            idsToCopy.includes(o.id),
          );
          setClipboard(objs);
        }
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "x") {
        const idsToCut =
          selectedMultiIds.length > 0
            ? selectedMultiIds
            : selectedObjectId
              ? [selectedObjectId]
              : [];
        if (idsToCut.length > 0) {
          e.preventDefault();
          const objs = currentScene.objects.filter((o) =>
            idsToCut.includes(o.id),
          );
          setClipboard(objs);
          updateScene({
            objects: currentScene.objects.filter(
              (o) => !idsToCut.includes(o.id),
            ),
          });
          setSelectedMultiIds([]);
          setSelectedObjectId(null);
        }
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "v") {
        if (clipboard.length > 0) {
          e.preventDefault();
          const newObjs = clipboard.map((o) => ({
            ...o,
            id: uuidv4(),
            x: o.x + 20,
            y: o.y + 20,
          }));
          updateScene({ objects: [...currentScene.objects, ...newObjs] });
          setSelectedMultiIds(newObjs.map((o) => o.id));
          if (newObjs.length === 1) setSelectedObjectId(newObjs[0].id);
        }
      }
    };
    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [
    history,
    project,
    clipboard,
    selectedObjectId,
    selectedMultiIds,
    currentScene,
  ]);

  // Keyboard nudging and duplication
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((!selectedObjectId && selectedMultiIds.length === 0) || isPlaying)
        return;
      // Don't nudge if typing in an input
      if (
        document.activeElement?.tagName === "INPUT" ||
        document.activeElement?.tagName === "TEXTAREA"
      )
        return;

      const idsToModify =
        selectedMultiIds.length > 0
          ? selectedMultiIds
          : selectedObjectId
            ? [selectedObjectId]
            : [];
      const objs = currentScene.objects.filter(
        (o) => idsToModify.includes(o.id) && !o.locked,
      );
      if (objs.length === 0) return;

      // Copy with Ctrl+C
      if ((e.ctrlKey || e.metaKey) && e.key === "c") {
        e.preventDefault();
        setClipboard(objs);
        return;
      }

      // Paste with Ctrl+V
      if ((e.ctrlKey || e.metaKey) && e.key === "v") {
        e.preventDefault();
        if (clipboard.length === 0) return;
        // Since we don't have mouse position in keyboard event, paste slightly offset from center or original
        const maxZ = Math.max(...currentScene.objects.map((o) => o.zIndex), 0);
        
        const newObjs = clipboard.map((o, i) => ({
          ...o,
          id: uuidv4(),
          x: o.x + 40,
          y: o.y + 40,
          zIndex: maxZ + i + 1,
          locked: false,
        }));

        setProject((p) => ({
          ...p,
          scenes: p.scenes.map((s) => {
            if (
              editorMode === "stage" &&
              s.id === currentScene.id
            ) {
              return {
                ...s,
                objects: [...s.objects, ...newObjs],
              };
            }
            return s;
          }),
          uiMenus: p.uiMenus?.map((m) => {
            if (
              editorMode === "ui_stage" &&
              m.id === currentScene.id
            ) {
              return {
                ...m,
                objects: [...m.objects, ...newObjs],
              };
            }
            return m;
          }),
        }));
        setSelectedMultiIds(newObjs.map(o => o.id));
        setSelectedObjectId(newObjs[0]?.id || null);
        return;
      }

      // Duplicate with Ctrl+D or Cmd+D
      if ((e.ctrlKey || e.metaKey) && e.key === "d") {
        e.preventDefault();
        const maxZ = Math.max(...currentScene.objects.map((o) => o.zIndex), 0);
        const newObjs = objs.map((obj, i) => ({
          ...obj,
          id: uuidv4(),
          x: obj.x + 20,
          y: obj.y + 20,
          zIndex: maxZ + i + 1,
        }));
        updateScene({ objects: [...currentScene.objects, ...newObjs] });
        setSelectedMultiIds(newObjs.map((o) => o.id));
        setSelectedObjectId(newObjs[0]?.id || null);
        return;
      }

      const step = e.shiftKey ? 10 : 1;
      let dx = 0;
      let dy = 0;

      if (e.key === "ArrowUp") dy = -step;
      else if (e.key === "ArrowDown") dy = step;
      else if (e.key === "ArrowLeft") dx = -step;
      else if (e.key === "ArrowRight") dx = step;
      else if (e.key === "Delete" || e.key === "Backspace") {
        updateScene({
          objects: currentScene.objects.filter(
            (o) => !idsToModify.includes(o.id),
          ),
        });
        setSelectedMultiIds([]);
        setSelectedObjectId(null);
        return;
      }

      if (dx !== 0 || dy !== 0) {
        e.preventDefault();
        // Since we are nudging array of objects, we use updateScene directly instead of updateObject so they move together
        updateScene({
          objects: currentScene.objects.map((o) => {
            if (idsToModify.includes(o.id) && !o.locked) {
              return { ...o, x: o.x + dx, y: o.y + dy };
            }
            return o;
          }),
        });
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [selectedObjectId, selectedMultiIds, currentScene.objects, isPlaying, clipboard]);

  const handleExport = () => {
    try {
      const exportProject = prepareProjectForExport(project, {
        assetScope: "used",
        includeEmbeddedAssetData: "fallback",
      });
      const html = generateExportHtml(exportProject);
      const blob = new Blob([html], { type: "text/html" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      const cleanName = project.name ? project.name.replace(/[^a-z0-9]/gi, '_').toLowerCase() : 'game';
      a.download = `${cleanName}.html`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (err) {
      showError("Failed to export HTML: " + err);
      console.error(err);
    }
  };

  const togglePlayMode = () => {
    const newState = !isPlaying;
    if (newState) {
      editorModeBeforePlayRef.current = editorMode;
      if (editorMode !== "stage" && editorMode !== "ui_stage") {
        setEditorMode("stage");
      }
    } else {
      setEditorMode(editorModeBeforePlayRef.current);
    }
    setIsPlaying(newState);
    setRuntimeOverrides({});
    if (newState) {
      setTriggeredObjects(new Set());
      setPlayerInventory([]);
      setCollectedObjects([]);
      setPlayerFlags([]);
      setPlayerTalkCounts({});
      setActiveQuests(
        project.quests?.filter((q) => q.autoStart).map((q) => q.id) || [],
      );
      setCompletedQuests([]);
      setTriggeredResponseIds(new Set());
      setIsNeedsHudOpen(true);
      setIsSkillsHudOpen(true);
      const defaultFactions: Record<string, number> = {};
      (project.factions || []).forEach((faction) => {
        defaultFactions[faction.id] = faction.defaultAffinity ?? 0;
      });
      (project.characters || []).forEach((character) => {
        defaultFactions[character.id] = character.defaultAffinity ?? 0;
      });
      setPlayerFactions(defaultFactions);
      const defaultNeeds: Record<string, number> = {};
      getNeedTrackIds(project).forEach((need) => {
        const definition = getNeedTrackDefinition(project, need);
        defaultNeeds[need] = Math.max(
          definition.min,
          Math.min(definition.max, definition.defaultValue),
        );
      });
      setPlayerNeeds(defaultNeeds);

      const defaultSkills: Record<string, number> = {};
      getSkillTrackIds(project).forEach((skill) => {
        const definition = getSkillTrackDefinition(project, skill);
        defaultSkills[skill] = Math.max(
          definition.min,
          Math.min(definition.max, definition.defaultValue),
        );
      });
      setPlayerSkills(defaultSkills);
      setGameTime(project.globalSettings.dayNightStartHour ?? 8);
      setGameDay(1);
    } else {
      setPlayerInventory([]);
      setCollectedObjects([]);
      setTriggeredObjects(new Set());
      setTriggeredResponseIds(new Set());
    }
    setActiveUiMenus(
      newState
        ? (project.uiMenus || [])
            .filter((menu) => menu.isOpenByDefault)
            .map((menu) => menu.id)
        : [],
    );
    setActiveDialogue(null);
    setPreviewDialogue(null);
    setIsInventoryOpen(false);
  };

  const CAVEBOT_ASSET_ROOT = "assets/_cavebot-assets";
  const REPOSITORY_MEDIA_EXTENSION =
    /\.(png|jpe?g|gif|webp|svg|mp3|wav|ogg|m4a|mp4|webm|js|ts)$/i;
  const normalizeRepoFileMatchName = (value?: string | null) =>
    (value || "")
      .trim()
      .replace(/^.*\//, "")
      .replace(
        /^(.+?\.(?:png|jpe?g|gif|webp|svg|mp3|wav|ogg|m4a|mp4|webm|js|ts))(?:_crop.*)?$/i,
        "$1",
      )
      .replace(/(?:_crop)+$/i, "")
      .toLowerCase();
  const normalizeRepoFileMatchStem = (value?: string | null) =>
    normalizeRepoFileMatchName(value).replace(REPOSITORY_MEDIA_EXTENSION, "");
  const createRepositoryAsset = (file: {
    name?: string;
    path: string;
    download_url?: string;
  }): Asset => {
    const name = file.name || file.path.split("/").pop() || file.path;
    const relativePath = file.path.startsWith(CAVEBOT_ASSET_ROOT)
      ? file.path.slice(CAVEBOT_ASSET_ROOT.length).replace(/^\/+/, "")
      : file.path.replace(/^assets\/?/, "");
    const parts = relativePath.split("/");
    parts.pop();
    const category = parts.length > 0 ? parts.join("/") : "root";
    const encodedPath = file.path
      .split("/")
      .map((p: string) => encodeURIComponent(p))
      .join("/");
    const isScript = file.path.match(/\.(js|ts)$/i);
    const isAudio = file.path.match(/\.(mp3|wav|ogg|m4a)$/i);
    const isVideo = file.path.match(/\.(mp4|webm)$/i);

    return {
      id: `github:${file.path}`,
      type: isScript
        ? "script"
        : isAudio
          ? "audio"
          : isVideo
            ? "video"
            : "image",
      category,
      src:
        file.download_url ||
        `https://raw.githubusercontent.com/thenabu222/entropic-ai/main/${encodedPath}`,
      name,
    };
  };

  const fetchFromGitHub = async (folderPath = "", force = false) => {
    const relativeFolder = folderPath
      .split("/")
      .filter((part) => part && part !== "." && part !== "..")
      .join("/");
    if (!force && loadedRepositoryFolders.includes(relativeFolder)) {
      setRepositoryFetchStatus(
        relativeFolder
          ? `Already loaded ${relativeFolder}.`
          : "Repo root already loaded.",
      );
      return;
    }
    setIsFetchingGithub(true);
    setRepositoryFetchStatus(
      relativeFolder ? `Loading ${relativeFolder}…` : "Loading repo files…",
    );
    try {
      const headers: HeadersInit = {};
      if (import.meta.env.VITE_GITHUB_TOKEN) {
        headers["Authorization"] =
          `token ${import.meta.env.VITE_GITHUB_TOKEN}`;
      }
      const repositoryPath = relativeFolder
        ? `${CAVEBOT_ASSET_ROOT}/${relativeFolder}`
        : CAVEBOT_ASSET_ROOT;
      const encodedFolder = repositoryPath
        .split("/")
        .filter(Boolean)
        .map((part) => encodeURIComponent(part))
        .join("/");
      const response = await fetch(
        `https://api.github.com/repos/thenabu222/entropic-ai/contents/${encodedFolder}`,
        { headers },
      );
      if (!response.ok) throw new Error(`API Error: ${response.status}`);
      const directoryItems = await response.json();
      if (!Array.isArray(directoryItems)) {
        throw new Error("Repository folder did not return a directory.");
      }

      const discoveredFolders = directoryItems
        .filter((item: any) => item.type === "dir")
        .map((item: any) =>
          (item.path as string)
            .slice(CAVEBOT_ASSET_ROOT.length)
            .replace(/^\/+/, ""),
        )
        .filter(Boolean);
      setRepositoryFolders((current) =>
        Array.from(new Set([...current, ...discoveredFolders])).sort(),
      );

      const validFiles = directoryItems.filter(
        (file: any) =>
          file.type === "file" &&
          file.path &&
          file.path.match(REPOSITORY_MEDIA_EXTENSION),
      );

      const visibleScenes = [...(project.scenes || []), ...(project.uiMenus || [])];
      const orphanNames = new Set<string>();
      const orphanStems = new Set<string>();
      visibleScenes.forEach((scene) => {
        (scene.objects || []).forEach((obj) => {
          if (!obj._assetId || obj.src || obj.isText || obj.isHitbox || obj.isUiElement) {
            return;
          }
          const name = normalizeRepoFileMatchName(obj.name);
          const stem = normalizeRepoFileMatchStem(obj.name);
          if (name) orphanNames.add(name);
          if (stem) orphanStems.add(stem);
        });
      });

      let recoveredAssets: Asset[] = [];
      if (orphanNames.size > 0 || orphanStems.size > 0) {
        try {
          const treeResponse = await fetch(
            "https://api.github.com/repos/thenabu222/entropic-ai/git/trees/main?recursive=1",
            { headers },
          );
          if (treeResponse.ok) {
            const treeData = await treeResponse.json();
            const treeFiles = Array.isArray(treeData.tree) ? treeData.tree : [];
            recoveredAssets = treeFiles
              .filter(
                (file: any) =>
                  file.type === "blob" &&
                  typeof file.path === "string" &&
                  file.path.startsWith("assets/") &&
                  file.path.match(REPOSITORY_MEDIA_EXTENSION),
              )
              .filter((file: any) => {
                const name = normalizeRepoFileMatchName(file.path);
                const stem = normalizeRepoFileMatchStem(file.path);
                return orphanNames.has(name) || orphanStems.has(stem);
              })
              .map((file: any) => createRepositoryAsset({ path: file.path }));
          }
        } catch (recoveryError) {
          console.warn("Repository relink scan failed", recoveryError);
        }
      }

      const newAssets: Asset[] = Array.from(
        new Map(
          [...validFiles.map((file: any) => createRepositoryAsset(file)), ...recoveredAssets].map(
            (asset) => [asset.id, asset],
          ),
        ).values(),
      );

      setProject((p) => {
        let updatedAssets = [...p.assets];
        const srcReplacements = new Map<string, string>();

        newAssets.forEach((newA) => {
          const existingIndex = updatedAssets.findIndex(
            (asset) =>
              asset.id === newA.id ||
              (asset.src === newA.src && asset.name === newA.name),
          );

          if (existingIndex !== -1) {
            srcReplacements.set(
              updatedAssets[existingIndex].src,
              newA.src,
            );
            updatedAssets[existingIndex] = {
              ...updatedAssets[existingIndex],
              ...newA,
            };
          } else {
            updatedAssets = [newA, ...updatedAssets];
          }
        });
        const updatedAssetsById = new Map(
          updatedAssets.map((asset) => [asset.id, asset]),
        );
        const newAssetsByName = new Map(
          newAssets
            .map((asset) => [normalizeRepoFileMatchName(asset.name), asset] as const)
            .filter(([name]) => Boolean(name)),
        );

        const migrateObjects = (scenes: Scene[]) => {
          return scenes.map((scene) => ({
            ...scene,
            objects: scene.objects.map((obj) => {
              const updatedSrc = srcReplacements.get(obj.src);
              if (updatedSrc) return { ...obj, src: updatedSrc };
              const existingAsset = obj._assetId
                ? updatedAssetsById.get(obj._assetId)
                : undefined;
              const hasLiveAsset =
                Boolean(existingAsset && getAssetDisplaySrc(existingAsset));
              if (hasLiveAsset || obj.src || !obj._assetId) return obj;
              const nameMatchedAsset = newAssetsByName.get(
                normalizeRepoFileMatchName(obj.name),
              );
              return nameMatchedAsset
                ? {
                    ...obj,
                    _assetId: nameMatchedAsset.id,
                    src: nameMatchedAsset.src,
                  }
                : obj;
            }),
          }));
        };

        return {
          ...p,
          assets: updatedAssets,
          scenes: migrateObjects(p.scenes || []),
          uiMenus: migrateObjects(p.uiMenus || []),
        };
      });
      setLoadedRepositoryFolders((current) =>
        Array.from(new Set([...current, relativeFolder])),
      );
      setRepositoryFetchStatus(
        `${relativeFolder || "Repo root"}: ${validFiles.length} file${
          validFiles.length === 1 ? "" : "s"
        }, ${discoveredFolders.length} folder${
          discoveredFolders.length === 1 ? "" : "s"
        }${recoveredAssets.length ? `, ${recoveredAssets.length} relinked` : ""}.`,
      );
      showError(
        `${relativeFolder || "Repo root"} loaded: ${validFiles.length} file${
          validFiles.length === 1 ? "" : "s"
        }, ${discoveredFolders.length} folder${
          discoveredFolders.length === 1 ? "" : "s"
        }.`,
      );
    } catch (error: any) {
      console.error("GitHub fetch failed", error);
      setRepositoryFetchStatus(
        `Repo load failed: ${error.message || "Network Error"}.`,
      );
      showError(
        `Failed to open repo folder: ${error.message || "Network Error"}.`,
      );
    } finally {
      setIsFetchingGithub(false);
    }
  };

  // Quick Edit UI Dragging
  useEffect(() => {
    if (!quickEditDragging) return;
    const handlePointerMove = (e: PointerEvent) => {
      setQuickEditPos({
        x:
          quickEditDragging.startPos.x + (e.clientX - quickEditDragging.startX),
        y:
          quickEditDragging.startPos.y + (e.clientY - quickEditDragging.startY),
      });
    };
    const stopDrag = () => setQuickEditDragging(null);
    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", stopDrag);
    window.addEventListener("pointercancel", stopDrag);
    window.addEventListener("blur", stopDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", stopDrag);
      window.removeEventListener("pointercancel", stopDrag);
      window.removeEventListener("blur", stopDrag);
    };
  }, [quickEditDragging]);

  // Sidebar Resizing Logic
  useEffect(() => {
    const handlePointerMove = (e: PointerEvent) => {
      if (document.body.classList.contains("resizing-left-sidebar")) {
        setLeftSidebarWidth((w) => {
          const newWidth = e.clientX;
          if (newWidth < 120) return 0;
          if (w === 0 && newWidth > 30) return 256;
          return Math.max(0, Math.min(800, newWidth));
        });
      } else if (document.body.classList.contains("resizing-right-sidebar")) {
        setRightSidebarWidth((w) => {
          const newWidth = document.body.clientWidth - e.clientX;
          if (newWidth < 120) return 0;
          if (w === 0 && newWidth > 30) return 288;
          return Math.max(0, Math.min(760, newWidth));
        });
      }
    };
    const stopResize = () => {
      document.body.classList.remove("resizing-left-sidebar");
      document.body.classList.remove("resizing-right-sidebar");
    };
    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", stopResize);
    window.addEventListener("pointercancel", stopResize);
    window.addEventListener("blur", stopResize);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", stopResize);
      window.removeEventListener("pointercancel", stopResize);
      window.removeEventListener("blur", stopResize);
    };
  }, []);

  useEffect(() => {
    const handleClick = () => {
      if (contextMenu) setContextMenu(null);
    };
    window.addEventListener("pointerdown", handleClick);
    return () => window.removeEventListener("pointerdown", handleClick);
  }, [contextMenu]);

  const moveZIndex = (id: string, dir: 1 | -1) => {
    const obj = currentScene.objects.find((o) => o.id === id);
    if (!obj) return;
    updateObject(id, { zIndex: Math.max(0, obj.zIndex + dir) });
  };

  const [previewDialogueText, _setPreviewDialogue] = useState<string | null>(
    null,
  );
  const previewDialogueRef = useRef<number | NodeJS.Timeout | null>(null);
  const setPreviewDialogue = (text: string | null) => {
    _setPreviewDialogue(text);
    if (previewDialogueRef.current) clearTimeout(previewDialogueRef.current);
    // Dialogues must be clicked to close
  };
  const previewDialogue = previewDialogueText;

  const isLoreEntryVisible = (entry: LoreEntry) =>
    !entry.requiredFlagId ||
    playerFlags.includes(entry.requiredFlagId) ||
    unlockedLoreEntryIds.includes(entry.id);

  const unlockLoreEntry = (entryId?: string, showNow = false) => {
    if (!entryId) return;
    const entry = (project.loreEntries || []).find((candidate) => candidate.id === entryId);
    if (!entry) return;

    setUnlockedLoreEntryIds((prev) =>
      prev.includes(entryId) ? prev : [...prev, entryId],
    );

    if (showNow) {
      const label =
        entry.entryType === "quest_note"
          ? "Quest Note"
          : entry.entryType === "journal"
            ? "Journal"
            : "Lore";
      setPreviewDialogue(`${label}: ${entry.title}\n\n${entry.content || "Added to your almanac."}`);
    }
  };

  const completeQuestObjective = (objectiveId?: string) => {
    if (!objectiveId) return;
    const quest = (project.quests || []).find((candidate) =>
      (candidate.objectives || []).some((objective) => objective.id === objectiveId),
    );
    const objective = quest?.objectives?.find((candidate) => candidate.id === objectiveId);
    if (!quest || !objective) return;

    setCompletedQuestObjectives((prev) =>
      prev.includes(objectiveId) ? prev : [...prev, objectiveId],
    );
    setActiveQuests((prev) =>
      prev.includes(quest.id) || completedQuests.includes(quest.id)
        ? prev
        : [...prev, quest.id],
    );
    setPreviewDialogue(`Quest step complete: ${objective.description || quest.name}`);
  };

  const applyCraftingOutcomes = (recipe: CraftingRecipe) => {
    (recipe.outcomes || []).forEach((outcome) => {
      if (!outcome.targetId) return;

      if (outcome.type === "set_flag") {
        setPlayerFlags((prev) =>
          prev.includes(outcome.targetId) ? prev : [...prev, outcome.targetId],
        );
      } else if (outcome.type === "clear_flag") {
        setPlayerFlags((prev) =>
          prev.filter((flag) => flag !== outcome.targetId),
        );
      } else if (outcome.type === "change_need") {
        setPlayerNeeds((prev) => ({
          ...prev,
          [outcome.targetId]: Math.max(
            0,
            Math.min(
              100,
              (prev[outcome.targetId] || 0) + (outcome.amount || 0),
            ),
          ),
        }));
      } else if (outcome.type === "change_skill") {
        setPlayerSkills((prev) => ({
          ...prev,
          [outcome.targetId]: Math.max(
            0,
            Math.min(
              20,
              (prev[outcome.targetId] || 0) + (outcome.amount || 0),
            ),
          ),
        }));
      } else if (outcome.type === "start_quest") {
        setActiveQuests((prev) =>
          prev.includes(outcome.targetId) ||
          completedQuests.includes(outcome.targetId)
            ? prev
            : [...prev, outcome.targetId],
        );
      } else if (outcome.type === "complete_quest") {
        setActiveQuests((prev) =>
          prev.filter((questId) => questId !== outcome.targetId),
        );
        setCompletedQuests((prev) =>
          prev.includes(outcome.targetId) ? prev : [...prev, outcome.targetId],
        );
      }
    });
  };

  const normalizeRuntimeLookup = (value?: string | null) =>
    (value || "")
      .trim()
      .replace(/^.*\//, "")
      .replace(/\.[a-z0-9]+$/i, "")
      .replace(/(?:_crop|_cropped|_copy|copy)+$/gi, "")
      .replace(/[^a-z0-9]+/gi, "")
      .toLowerCase();

  const addRuntimeInventoryItem = (itemId: string) => {
    if (!itemId) return;
    setPlayerInventory((prev) => (prev.includes(itemId) ? prev : [...prev, itemId]));
  };

  const relationshipBaseValue = (targetId: string) => {
    const character = (project.characters || []).find(
      (candidate) => candidate.id === targetId,
    );
    if (character) return character.defaultAffinity ?? 0;
    const faction = (project.factions || []).find(
      (candidate) => candidate.id === targetId,
    );
    return faction?.defaultAffinity ?? 0;
  };

  const resolveRuntimeRelationshipTargetId = (
    explicitTargetId?: string | null,
    obj?: SceneObject,
  ) => {
    const rawTarget =
      explicitTargetId ||
      obj?.reputationEffect?.npcId ||
      obj?.characterId ||
      obj?.affinityId ||
      "";
    if (!rawTarget) return "";
    const normalizedTarget = normalizeRuntimeLookup(rawTarget);
    const character = (project.characters || []).find(
      (candidate) =>
        candidate.id === rawTarget ||
        normalizeRuntimeLookup(candidate.name) === normalizedTarget,
    );
    if (character) return character.id;
    const faction = (project.factions || []).find(
      (candidate) =>
        candidate.id === rawTarget ||
        normalizeRuntimeLookup(candidate.name) === normalizedTarget,
    );
    return faction?.id || rawTarget;
  };

  const changeRuntimeRelationship = (targetId: string, amount: number) => {
    if (!targetId || !Number.isFinite(amount)) return;
    setPlayerFactions((prev) => ({
      ...prev,
      [targetId]: Math.max(
        -100,
        Math.min(100, (prev[targetId] ?? relationshipBaseValue(targetId)) + amount),
      ),
    }));
  };

  const inferInventoryItemForObject = (obj: SceneObject) => {
    if (obj.giveItemId) return obj.giveItemId;
    const linkedAssetId = obj._assetId;
    const linkedAssetSrc = obj.src;
    const normalizedObjectName = normalizeRuntimeLookup(obj.name);
    const normalizedObjectSrc = normalizeRuntimeLookup(linkedAssetSrc);
    const matchingItem = (project.inventoryItems || []).find((item) => {
      if (linkedAssetId && item.iconAssetId === linkedAssetId) return true;
      const normalizedItemName = normalizeRuntimeLookup(item.name);
      if (
        normalizedObjectName &&
        normalizedItemName &&
        (normalizedItemName === normalizedObjectName ||
          normalizedObjectName.includes(normalizedItemName) ||
          normalizedItemName.includes(normalizedObjectName))
      ) {
        return true;
      }
      if (!item.iconAssetId) return false;
      const iconAsset = project.assets.find(
        (asset) => asset.id === item.iconAssetId,
      );
      const iconSrc = getAssetDisplaySrc(iconAsset);
      if (linkedAssetSrc && iconSrc === linkedAssetSrc) return true;
      const normalizedIconSrc = normalizeRuntimeLookup(iconSrc);
      const normalizedIconName = normalizeRuntimeLookup(iconAsset?.name);
      return !!(
        normalizedObjectSrc &&
        ((normalizedIconSrc && normalizedIconSrc === normalizedObjectSrc) ||
          (normalizedIconName &&
            (normalizedIconName === normalizedObjectSrc ||
              normalizedObjectSrc.includes(normalizedIconName))))
      );
    });
    return matchingItem?.id || "";
  };

  const handleObjectClick = (obj: SceneObject, isChainedResponse = false) => {
    if (!isPlaying) return;
    if (!isChainedResponse) {
      const primaryRuleState = createRuntimeGameState(project.currentSceneId, {
        inventory: [...playerInventory],
        flags: Object.fromEntries(playerFlags.map((flag) => [flag, true])),
        skills: { ...playerSkills },
        needs: { ...playerNeeds },
        relationships: { ...playerFactions },
        activeQuests: [...activeQuests],
        completedQuests: [...completedQuests],
        completedQuestObjectives: [...completedQuestObjectives],
        unlockedLoreEntryIds: [...unlockedLoreEntryIds],
        collectedObjects: [...collectedObjects],
        activeUiMenus: [...activeUiMenus],
        triggeredRuleIds: [
          ...triggeredObjects,
          ...triggeredResponseIds,
        ],
        runtimePositions: { ...runtimeOverrides },
        time: gameTime,
        day: gameDay,
      });
      if (
        !evaluateRuleConditions(
          obj.conditions,
          obj.conditionMode || "all",
          primaryRuleState,
        )
      ) {
        return;
      }
      if (obj.triggerOnce && triggeredObjects.has(obj.id)) return;
      if (obj.triggerOnce) {
        setTriggeredObjects((prev) => new Set(prev).add(obj.id));
      }
    }

    if (obj.audioSrc) {
      const audioAsset = project.assets.find((a) => a.id === obj.audioSrc);
      playRuntimeAudioAsset(audioAsset);
    }

    // Evaluate global Skill requirement block (if the object has a skill set to something other than 'none' and interaction is NOT skill_check)
    if (
      obj.requiredSkill &&
      obj.requiredSkill !== "none" &&
      obj.interaction !== "skill_check"
    ) {
      const diff = obj.skillCheckDifficulty || 0;
      const roll =
        Math.floor(Math.random() * 20) +
        1 +
        (playerSkills[obj.requiredSkill] || 0);
      if (roll < diff) {
        setPreviewDialogue(
          `[Skill Check Failed] ${obj.requiredSkill} roll: ${roll} vs ${diff}`,
        );

        return; // Stop interaction!
      }
    }

    // Process Needs Effect
    if (obj.needsEffect) {
      try {
        const effect =
          typeof obj.needsEffect === "string"
            ? JSON.parse(obj.needsEffect)
            : obj.needsEffect;
        let changed = false;
        const nextNeeds = { ...playerNeeds };
        for (const [key, val] of Object.entries(effect) as [string, number][]) {
          if (val) {
            nextNeeds[key] = (nextNeeds[key] || 0) + val;
            changed = true;
          }
        }
        if (changed) setPlayerNeeds(nextNeeds);
      } catch (e) {
        console.error("Failed to parse needs effect", e);
      }
    }

    if (obj.grantSkill && obj.grantSkill !== "none") {
      const amount = obj.grantSkillValue || 1;
      setPlayerSkills((prev) => ({
        ...prev,
        [obj.grantSkill as string]: Math.min(
          20,
          (prev[obj.grantSkill as string] || 0) + amount,
        ),
      }));
      setPreviewDialogue(`Gained +${amount} ${obj.grantSkill}!`);
    }

    if (obj.timeCost) {
      setGameTime((prev) => (prev + (obj.timeCost || 0)) % 24);
    }

    if (obj.reputationEffect) {
      const effect = obj.reputationEffect;
      const targetId = resolveRuntimeRelationshipTargetId(effect.npcId, obj);
      changeRuntimeRelationship(targetId, effect.value);
    }

    if (obj.requireItemId && !playerInventory.includes(obj.requireItemId)) {
      const item = project.inventoryItems.find(
        (i) => i.id === obj.requireItemId,
      );
      setPreviewDialogue(
        `You need ${item?.name || "a specific item"} to interact with this.`,
      );

      return;
    }

    if (
      obj.requireItemId &&
      obj.consumeRequiredItem &&
      playerInventory.includes(obj.requireItemId)
    ) {
      setPlayerInventory((prev) => {
        const next = [...prev];
        const idx = next.indexOf(obj.requireItemId!);
        if (idx !== -1) next.splice(idx, 1);
        return next;
      });
      const reqItem = project.inventoryItems.find(
        (i) => i.id === obj.requireItemId,
      );
      if (reqItem) {
        setPreviewDialogue(`You used up: ${reqItem.name}`);
      }
    }

    if (obj.interaction === "dialogue") {
      if (obj.dialogueTreeId) {
        const tree = project.dialogueTrees.find(
          (t) => t.id === obj.dialogueTreeId,
        );
        const startNodeId =
          tree && tree.nodes.some((node) => node.id === tree.startNodeId)
            ? tree.startNodeId
            : tree?.nodes[0]?.id || null;
        if (tree && startNodeId) {
          setPlayerTalkCounts((prev) => ({
            ...prev,
            [tree.id]: (prev[tree.id] || 0) + 1,
          }));
          setPlayerFlags((prev) =>
            prev.includes(`talked_${tree.id}`)
              ? prev
              : [...prev, `talked_${tree.id}`],
          );
          setPreviewDialogue(null);
          setActiveDialogue({ treeId: tree.id, nodeId: startNodeId });
        }
      } else if (obj.interactionData) {
        setPreviewDialogue(obj.interactionData);
      }
    } else if (
      obj.interaction === "give-item" ||
      obj.interaction === "collect"
    ) {
      const itemIdToGive = inferInventoryItemForObject(obj);
      if (itemIdToGive) {
        addRuntimeInventoryItem(itemIdToGive);
        const item = project.inventoryItems.find(
          (i) => i.id === itemIdToGive,
        );
        setPreviewDialogue(
          obj.interactionData || `You obtained: ${item?.name || "an item"}!`,
        );
      } else {
        setPreviewDialogue(obj.interactionData || `You interacted with this!`);
      }

      if (obj.interaction === "collect") {
        setCollectedObjects((prev) =>
          prev.includes(obj.id) ? prev : [...prev, obj.id],
        );
      }
    } else if (obj.interaction === "link" && obj.interactionData) {
      window.open(obj.interactionData, "_blank");
    } else if (obj.interaction === "modify_number" && obj.targetUiId) {
      const amount = parseFloat(obj.interactionData || "0");

      const updateObjHelper = (s: Scene) => {
        return {
          ...s,
          objects: s.objects.map((o) => {
            if (o.id === obj.targetUiId) {
              if (o.uiElementType === "progress") {
                return {
                  ...o,
                  uiValue: Math.max(
                    0,
                    Math.min(100, (o.uiValue || 0) + amount),
                  ),
                };
              } else if (o.isText && o.textContent !== undefined) {
                const currentNum = parseFloat(o.textContent || "0");
                if (!isNaN(currentNum))
                  return {
                    ...o,
                    textContent: (currentNum + amount).toString(),
                  };
              }
            }
            return o;
          }),
        };
      };

      setProject((prev) => ({
        ...prev,
        scenes: (prev.scenes || []).map(updateObjHelper),
        uiMenus: (prev.uiMenus || []).map(updateObjHelper),
      }));
    } else if (obj.interaction === "open_ui" && obj.targetUiId) {
      setActiveUiMenus((prev) => [...prev, obj.targetUiId!]);
    } else if (obj.interaction === "close_ui") {
      setActiveUiMenus((prev) => {
        if (obj.targetUiId) {
          return prev.filter((id) => id !== obj.targetUiId);
        }
        const next = [...prev];
        if (next.length > 0) next.pop(); // Close the topmost UI menu
        return next;
      });
    } else if (obj.interaction === "scene_change" && obj.interactionData) {
      const targetScene = project.scenes.find(
        (s) => s.id === obj.interactionData,
      );
      if (targetScene) {
        setTransition({ active: true, type: "fade" });
        setTimeout(() => {
          setProject((p) => ({ ...p, currentSceneId: targetScene.id }));
        }, 500);
        setTimeout(() => {
          setTransition({ active: false, type: "fade" });
        }, 1000);
      } else {
        showError(`Scene not found: ${obj.interactionData}`);
      }
    } else if (obj.interaction === "toggle_inventory") {
      togglePlayOverlay("inventory");
    } else if (obj.interaction === "toggle_needs_hud") {
      if (!project.globalSettings.enableNeeds) {
        setPreviewDialogue("Needs HUD is not enabled for this game.");
      } else {
        if (hideEditorHud || !isNeedsHudOpen) {
          setHideEditorHud(false);
          setIsNeedsHudOpen(true);
        } else {
          setIsNeedsHudOpen(false);
        }
      }
    } else if (obj.interaction === "toggle_skills_hud") {
      if (!project.globalSettings.enableTTRPGStats) {
        setPreviewDialogue("Skills HUD is not enabled for this game.");
      } else {
        if (hideEditorHud || !isSkillsHudOpen) {
          setHideEditorHud(false);
          setIsSkillsHudOpen(true);
        } else {
          setIsSkillsHudOpen(false);
        }
      }
    } else if (obj.interaction === "restart_scene") {
      setPreviewDialogue("");
      setPlayerInventory([]);
      setCollectedObjects([]);
      setRuntimeOverrides({});
    } else if (obj.interaction === "restart_game") {
      setPreviewDialogue("");
      setPlayerInventory([]);
      setCollectedObjects([]);
      setPlayerFlags([]);
      setActiveQuests(
        project.quests?.filter((q) => q.autoStart).map((q) => q.id) || [],
      );
      setCompletedQuests([]);
      setPlayerSkills({});
      setRuntimeOverrides({});
      setPlayerNeeds({});
      setActiveUiMenus([]);
      setIsInventoryOpen(false);
      setIsCraftingOpen(false);
      setIsQuestLogOpen(false);
      setIsSkillsOpen(false);
      setIsAlmanacOpen(false);
      setIsRelationshipsOpen(false);
      setIsSettingsOpen(false);
      setIsMapOpen(false);
      setIsNeedsHudOpen(true);
      setIsSkillsHudOpen(true);
      const firstScene = (project.scenes && project.scenes[0]) || null;
      if (firstScene) {
        setProject((p) => ({ ...p, currentSceneId: firstScene.id }));
      }
    } else if (obj.interaction === "toggle_fullscreen") {
      if (!document.fullscreenElement) {
        document.documentElement
          .requestFullscreen()
          .catch((err) => console.error("Fullscreen error", err));
      } else {
        document
          .exitFullscreen()
          .catch((err) => console.error("Exit fullscreen error", err));
      }
    } else if (obj.interaction === "toggle_mute") {
      setIsAudioMuted((previous) => {
        const next = !previous;
        if (bgmRef.current) bgmRef.current.muted = next;
        runtimeAudioRefs.current.forEach((audio) => {
          audio.muted = next;
        });
        setPreviewDialogue(next ? "Audio muted." : "Audio unmuted.");
        return next;
      });
    } else if (obj.interaction === "advance_day") {
      setPlayerFlags((prev) => prev.filter((f) => !f.startsWith("daily_")));
      setGameDay((prev) => prev + 1);
      setGameTime(project.globalSettings.dayNightStartHour ?? 6);
      setPreviewDialogue("A new day begins.");
    } else if (obj.interaction === "gift_item") {
      const charId = obj.interactionData;
      const char = (project.characters || []).find((c) => c.id === charId);
      if (!charId || !char) {
        setPreviewDialogue("No character configured for this interaction.");
      } else if (!selectedInventoryItemId) {
        setPreviewDialogue("Select an item in your inventory first.");
      } else {
        const pref = (char.giftPreferences || []).find((p) => p.itemId === selectedInventoryItemId);
        if (pref) {
          setPlayerFactions((prev) => ({
            ...prev,
            [charId]: Math.max(-100, Math.min(100, (prev[charId] ?? (char.defaultAffinity || 0)) + pref.change)),
          }));
          setPlayerInventory((prev) => prev.filter((id) => id !== selectedInventoryItemId));
          setSelectedInventoryItemId(null);
          setPreviewDialogue(pref.reactionText || (pref.change > 0 ? `${char.name} smiles. "Thank you."` : `${char.name} frowns. "I don't want this."`));
        } else {
          const itemDef = project.inventoryItems?.find((i) => i.id === selectedInventoryItemId);
          setPreviewDialogue(`${char.name} doesn't seem interested in ${itemDef?.name || "that"}.`);
        }
      }
    } else if (obj.interaction === "exit_game") {
      setIsPlaying(false);
    } else if (obj.interaction === "open_crafting") {
      togglePlayOverlay("crafting");
    } else if (obj.interaction === "open_quest_log") {
      togglePlayOverlay("questLog");
    } else if (obj.interaction === "open_skills") {
      togglePlayOverlay("skills");
    } else if (obj.interaction === "open_almanac") {
      togglePlayOverlay("almanac");
    } else if (obj.interaction === "unlock_lore_entry") {
      unlockLoreEntry(obj.interactionData, false);
    } else if (obj.interaction === "show_lore_entry") {
      unlockLoreEntry(obj.interactionData, true);
    } else if (obj.interaction === "open_map") {
      if (project.maps && project.maps.length > 0 && !activeFastTravelMapId) {
        setActiveFastTravelMapId(project.maps[0].id);
      }
      togglePlayOverlay("map");
    } else if (obj.interaction === "open_relationships") {
      togglePlayOverlay("relationships");
    } else if (obj.interaction === "open_settings") {
      togglePlayOverlay("settings");
    } else if (obj.interaction === "start_quest" && obj.interactionData) {
      if (
        !activeQuests.includes(obj.interactionData) &&
        !completedQuests.includes(obj.interactionData)
      ) {
        setActiveQuests((prev) => [...prev, obj.interactionData!]);
        const questName =
          project.quests?.find((q) => q.id === obj.interactionData)?.name ||
          "Quest";
        setPreviewDialogue(`Started Quest: ${questName}`);
      }
    } else if (obj.interaction === "complete_quest" && obj.interactionData) {
      if (activeQuests.includes(obj.interactionData)) {
        setActiveQuests((prev) =>
          prev.filter((id) => id !== obj.interactionData),
        );
        setCompletedQuests((prev) => [...prev, obj.interactionData!]);
        const questName =
          project.quests?.find((q) => q.id === obj.interactionData)?.name ||
          "Quest";
        setPreviewDialogue(`Completed Quest: ${questName}`);
      }
    } else if (obj.interaction === "complete_quest_objective") {
      completeQuestObjective(obj.interactionData);
    } else if (obj.interaction === "set_flag" && obj.interactionData) {
      if (!playerFlags.includes(obj.interactionData)) {
        setPlayerFlags((prev) => [...prev, obj.interactionData!]);
      }
    } else if (obj.interaction === "clear_flag" && obj.interactionData) {
      setPlayerFlags((prev) => prev.filter((f) => f !== obj.interactionData));
    } else if (obj.interaction === "toggle_flag" && obj.interactionData) {
      setPlayerFlags((prev) =>
        prev.includes(obj.interactionData!)
          ? prev.filter((f) => f !== obj.interactionData)
          : [...prev, obj.interactionData!],
      );
    } else if (obj.interaction === "show_object" && obj.interactionData) {
      setRuntimeOverrides((prev) => ({
        ...prev,
        [obj.interactionData!]: { ...prev[obj.interactionData!], hidden: false },
      }));
    } else if (obj.interaction === "hide_object" && obj.interactionData) {
      setRuntimeOverrides((prev) => ({
        ...prev,
        [obj.interactionData!]: { ...prev[obj.interactionData!], hidden: true },
      }));
    } else if (obj.interaction === "toggle_object" && obj.interactionData) {
      setRuntimeOverrides((prev) => {
        const cur = prev[obj.interactionData!];
        return {
          ...prev,
          [obj.interactionData!]: { ...cur, hidden: !cur?.hidden },
        };
      });
    } else if (obj.interaction === "save_game") {
      const stateToSave = {
        version: 1,
        currentSceneId: project.currentSceneId,
        inventory: playerInventory,
        needs: playerNeeds,
        time: gameTime,
        day: gameDay,
        skills: playerSkills,
        collectedObjects: collectedObjects,
        flags: playerFlags,
        relationships: playerFactions,
        activeQuests,
        completedQuests,
        completedQuestObjectives,
        unlockedLoreEntryIds,
        activeUiMenus,
        triggeredRuleIds: [
          ...triggeredObjects,
          ...triggeredResponseIds,
        ],
        runtimePositions: runtimeOverrides,
      };
      localStorage.setItem(
        `neocities_game_save_${project.id}`,
        JSON.stringify(stateToSave),
      );
      setPreviewDialogue("Game Saved!");
    } else if (obj.interaction === "load_game") {
      const saved = localStorage.getItem(`neocities_game_save_${project.id}`);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.inventory) setPlayerInventory(parsed.inventory);
          if (parsed.needs) setPlayerNeeds(parsed.needs);
          if (parsed.time) setGameTime(parsed.time);
          if (parsed.day) setGameDay(parsed.day);
          if (parsed.skills) setPlayerSkills(parsed.skills);
          if (parsed.collectedObjects)
            setCollectedObjects(parsed.collectedObjects);
          if (parsed.flags) setPlayerFlags(parsed.flags);
          if (parsed.relationships) setPlayerFactions(parsed.relationships);
          if (parsed.activeQuests) setActiveQuests(parsed.activeQuests);
          if (parsed.completedQuests)
            setCompletedQuests(parsed.completedQuests);
          if (parsed.completedQuestObjectives)
            setCompletedQuestObjectives(parsed.completedQuestObjectives);
          if (parsed.unlockedLoreEntryIds)
            setUnlockedLoreEntryIds(parsed.unlockedLoreEntryIds);
          if (parsed.activeUiMenus) setActiveUiMenus(parsed.activeUiMenus);
          if (parsed.triggeredRuleIds)
            {
              setTriggeredObjects(
                new Set(
                  parsed.triggeredRuleIds.filter(
                    (ruleId: string) => !ruleId.includes("::"),
                  ),
                ),
              );
              setTriggeredResponseIds(
                new Set(
                  parsed.triggeredRuleIds.filter((ruleId: string) =>
                    ruleId.includes("::"),
                  ),
                ),
              );
            }
          if (parsed.runtimePositions)
            setRuntimeOverrides(parsed.runtimePositions);
          if (parsed.currentSceneId) {
            setProject((previous) => ({
              ...previous,
              currentSceneId: parsed.currentSceneId,
            }));
          }
          setPreviewDialogue("Game Loaded!");
        } catch (e) {
          setPreviewDialogue("Load failed: Corrupted save data.");
        }
      } else {
        setPreviewDialogue("No save game found.");
      }
    } else if (obj.interaction === "skill_check") {
      const skill = obj.requiredSkill || "none";
      const dc = obj.skillCheckDifficulty || 10;
      const roll = Math.floor(Math.random() * 20) + 1;
      const modifier = 2; // Hardcoded for now, could be dynamic later
      const total = roll + modifier;
      const success = total >= dc;

      const skillName = skill.charAt(0).toUpperCase() + skill.slice(1);
      const resultText = success
        ? `[${skillName} Check: ${total} vs DC ${dc} - SUCCESS]\n\n${obj.interactionData || "You succeeded!"}`
        : `[${skillName} Check: ${total} vs DC ${dc} - FAILED]\n\nYou failed to interact with this object.`;

      setPreviewDialogue(resultText);
    } else if (obj.interaction === "sound" && obj.interactionData) {
      const audioAsset = project.assets.find(
        (a) => a.id === obj.interactionData,
      );
      playRuntimeAudioAsset(audioAsset);
    } else if (obj.interaction === "run_script" && obj.scriptAssetId) {
      const scriptAsset = project.assets.find(
        (a) => a.id === obj.scriptAssetId,
      );
      const scriptSrc = getAssetDisplaySrc(scriptAsset);
      if (scriptAsset && scriptSrc) {
        fetch(scriptSrc)
          .then((res) => res.text())
          .then((code) => {
            try {
              const context = {
                project,
                setProject,
                playerInventory,
                setPlayerInventory,
                setPreviewDialogue,
                obj,
              };
              const func = new Function("context", code);
              func(context);
            } catch (err) {
              console.error("Script execution failed", err);
              setPreviewDialogue("Script execution failed!");
            }
          })
          .catch((err) => {
            console.error("Failed to fetch script", err);
          });
      }
    } else if (obj.interaction === "play_cutscene" && obj.interactionData) {
      const videoAsset = project.assets.find(
        (a) => a.id === obj.interactionData,
      );
      const videoSrc = getAssetDisplaySrc(videoAsset);
      if (videoAsset && videoSrc) {
        setActiveCutscene({
          src: videoSrc,
          targetSceneId: obj.scriptAssetId || undefined,
        });
      }
    }

    if (!isChainedResponse && obj.clickResponses?.length) {
      const ruleState = createRuntimeGameState(project.currentSceneId, {
        inventory: [...playerInventory],
        flags: Object.fromEntries(playerFlags.map((flag) => [flag, true])),
        skills: { ...playerSkills },
        needs: { ...playerNeeds },
        relationships: { ...playerFactions },
        activeQuests: [...activeQuests],
        completedQuests: [...completedQuests],
        completedQuestObjectives: [...completedQuestObjectives],
        unlockedLoreEntryIds: [...unlockedLoreEntryIds],
        collectedObjects: [...collectedObjects],
        activeUiMenus: [...activeUiMenus],
        triggeredRuleIds: [...triggeredResponseIds],
        runtimePositions: { ...runtimeOverrides },
        time: gameTime,
        day: gameDay,
      });

      obj.clickResponses.forEach((response) => {
        const responseKey = `${obj.id}::${response.id}`;
        if (
          response.triggerOnce &&
          (triggeredResponseIds.has(responseKey) ||
            ruleState.triggeredRuleIds.includes(responseKey))
        ) {
          return;
        }
        if (
          !evaluateRuleConditions(
            response.conditions,
            response.conditionMode || "all",
            ruleState,
          )
        ) {
          return;
        }

        if (response.triggerOnce) {
          ruleState.triggeredRuleIds.push(responseKey);
          setTriggeredResponseIds((previous) => {
            const next = new Set(previous);
            next.add(responseKey);
            return next;
          });
        }

        handleObjectClick(
          {
            ...obj,
            id:
              response.interaction === "collect"
                ? obj.id
                : `${obj.id}::${response.id}`,
            interaction: response.interaction,
            interactionData: response.interactionData,
            giveItemId: response.giveItemId,
            dialogueTreeId: response.dialogueTreeId,
            targetUiId: response.targetUiId,
            scriptAssetId: response.scriptAssetId,
            clickResponses: [],
            triggerOnce: false,
            audioSrc: undefined,
            requireItemId: undefined,
            consumeRequiredItem: false,
            requiredSkill: "none",
            needsEffect: undefined,
            reputationEffect: undefined,
            grantSkill: undefined,
            timeCost: undefined,
          },
          true,
        );

        if (response.interaction === "set_flag" && response.interactionData) {
          ruleState.flags[response.interactionData] = true;
        } else if (
          (response.interaction === "give-item" ||
            response.interaction === "collect") &&
          response.giveItemId
        ) {
          ruleState.inventory.push(response.giveItemId);
        } else if (
          response.interaction === "start_quest" &&
          response.interactionData
        ) {
          ruleState.activeQuests.push(response.interactionData);
        } else if (
          response.interaction === "complete_quest" &&
          response.interactionData
        ) {
          ruleState.activeQuests = ruleState.activeQuests.filter(
            (questId) => questId !== response.interactionData,
          );
          ruleState.completedQuests.push(response.interactionData);
        } else if (
          response.interaction === "complete_quest_objective" &&
          response.interactionData
        ) {
          ruleState.completedQuestObjectives.push(response.interactionData);
        } else if (
          response.interaction === "scene_change" &&
          response.interactionData
        ) {
          ruleState.currentSceneId = response.interactionData;
        } else if (response.interaction === "open_ui" && response.targetUiId) {
          ruleState.activeUiMenus.push(response.targetUiId);
        } else if (
          (response.interaction === "unlock_lore_entry" ||
            response.interaction === "show_lore_entry") &&
          response.interactionData
        ) {
          ruleState.unlockedLoreEntryIds.push(response.interactionData);
        }
      });
    }
  };

  const handleShellControlClick = (
    control: NonNullable<
      NonNullable<Project["globalSettings"]["deviceFrame"]>["controls"]
    >[number],
  ) => {
    handleObjectClick({
      id: `shell-control::${control.id}`,
      name: control.name,
      src: "",
      x: control.x,
      y: control.y,
      width: control.width,
      height: control.height,
      rotation: 0,
      zIndex: 5000,
      opacity: 1,
      locked: true,
      cursor: control.cursor || "pointer",
      cursorAssetId: control.cursorAssetId,
      animation: "none",
      interaction: "none",
      clickResponses: control.clickResponses,
      blendMode: "normal",
      parallaxSpeed: 1,
      hasPhysics: false,
    });
  };

  const usedAssetSrcs = new Set(
    project.scenes.flatMap((s) => s.objects.map((o) => o.src).filter(Boolean)),
  );
  const uiBg = project.globalSettings.uiColorBackground || "#08060d";
  const uiPrimary =
    (isPlaying ? playerUiColor : null) ||
    project.globalSettings.uiColorPrimary ||
    "#00ffcc";
  const uiSecondary = project.globalSettings.uiColorSecondary || "#94a3b8";
  const uiFont = project.globalSettings.uiFontFamily || "sans-serif";
  const uiRadius = `${project.globalSettings.uiBorderRadius ?? 8}px`;
  const legacyHudScale = project.globalSettings.hudScale ?? 1;
  const hudNeedsScale =
    project.globalSettings.hudNeedsScale ?? legacyHudScale;
  const hudSkillsScale =
    project.globalSettings.hudSkillsScale ?? legacyHudScale;
  const hudButtonsScale =
    project.globalSettings.hudButtonsScale ?? legacyHudScale;
  const hudNeedsScaleX =
    project.globalSettings.hudNeedsScaleX ?? hudNeedsScale;
  const hudNeedsScaleY =
    project.globalSettings.hudNeedsScaleY ?? hudNeedsScale;
  const hudSkillsScaleX =
    project.globalSettings.hudSkillsScaleX ?? hudSkillsScale;
  const hudSkillsScaleY =
    project.globalSettings.hudSkillsScaleY ?? hudSkillsScale;
  const hudButtonsScaleX =
    project.globalSettings.hudButtonsScaleX ?? hudButtonsScale;
  const hudButtonsScaleY =
    project.globalSettings.hudButtonsScaleY ?? hudButtonsScale;
  const hudOverlay = project.globalSettings.hudOverlay;
  const hudOverlayAsset = hudOverlay?.assetId
    ? project.assets.find((asset) => asset.id === hudOverlay.assetId)
    : undefined;
  const hudOverlaySrc = getAssetDisplaySrc(hudOverlayAsset);
  const getHudOverlayStyle = (): React.CSSProperties => {
    const position = hudOverlay?.position || "stretch";
    const legacySize = (hudOverlay?.scale ?? 1) * 100;
    const widthPercent = hudOverlay?.widthPercent ?? legacySize;
    const heightPercent = hudOverlay?.heightPercent ?? legacySize;
    const offsetX = hudOverlay?.offsetX || 0;
    const offsetY = hudOverlay?.offsetY || 0;
    const anchors: Record<string, React.CSSProperties> = {
      center: {
        left: "50%",
        top: "50%",
        transform: `translate(-50%, -50%) translate(${offsetX}px, ${offsetY}px)`,
      },
      "top-left": {
        left: 0,
        top: 0,
        transform: `translate(${offsetX}px, ${offsetY}px)`,
      },
      "top-right": {
        right: 0,
        top: 0,
        transform: `translate(${offsetX}px, ${offsetY}px)`,
      },
      "bottom-left": {
        left: 0,
        bottom: 0,
        transform: `translate(${offsetX}px, ${offsetY}px)`,
      },
      "bottom-right": {
        right: 0,
        bottom: 0,
        transform: `translate(${offsetX}px, ${offsetY}px)`,
      },
    };

    return {
      ...(position === "stretch"
        ? { inset: 0, width: "100%", height: "100%" }
        : {
            width: `${widthPercent}%`,
            height: `${heightPercent}%`,
            ...anchors[position],
          }),
      backgroundImage: hudOverlaySrc
        ? `url('${hudOverlaySrc}')`
        : undefined,
      backgroundSize:
        hudOverlay?.fit === "contain" ? "contain" : "100% 100%",
      backgroundPosition: "center",
      backgroundRepeat: "no-repeat",
      mixBlendMode: (hudOverlay?.blendMode || "normal") as any,
      opacity: hudOverlay?.opacity ?? 1,
      pointerEvents: hudOverlay?.pointerEvents === "auto" ? "auto" : "none",
    };
  };
  const deviceFrame = project.globalSettings.deviceFrame;
  const deviceFrameAsset = deviceFrame
    ? project.assets.find((asset) => asset.id === deviceFrame.assetId)
    : undefined;
  const deviceFrameSrc = getAssetDisplaySrc(deviceFrameAsset);
  const showDeviceFrame = !!(
    deviceFrame &&
    deviceFrameAsset &&
    deviceFrameSrc &&
    (isPlaying || editorMode === "stage" || editorMode === "ui_stage")
  );
  const coordinateScene =
    editorMode === "ui_stage" && !isPlaying
      ? project.scenes.find((scene) => scene.id === project.currentSceneId) ||
        project.scenes[0] ||
        currentScene
      : currentScene;
  const logicalStageWidth =
    coordinateScene.width || project.globalSettings.stageWidth || 800;
  const logicalStageHeight =
    coordinateScene.height || project.globalSettings.stageHeight || 600;
  const deviceFramePlayInset = 0;
  const deviceFramePlayableWidth = showDeviceFrame
    ? Math.max(1, deviceFrame!.screen.width - deviceFramePlayInset * 2)
    : logicalStageWidth;
  const deviceFramePlayableHeight = showDeviceFrame
    ? Math.max(1, deviceFrame!.screen.height - deviceFramePlayInset * 2)
    : logicalStageHeight;
  const deviceFrameUniformScale = showDeviceFrame
    ? Math.min(
        deviceFramePlayableWidth / logicalStageWidth,
        deviceFramePlayableHeight / logicalStageHeight,
      )
    : 1;
  const deviceFrameStageScaleX = showDeviceFrame
    ? isPlaying
      ? deviceFramePlayableWidth / logicalStageWidth
      : deviceFrameUniformScale
    : 1;
  const deviceFrameStageScaleY = showDeviceFrame
    ? isPlaying
      ? deviceFramePlayableHeight / logicalStageHeight
      : deviceFrameUniformScale
    : 1;
  const deviceFrameStageLeft = showDeviceFrame
    ? isPlaying
      ? deviceFrame!.screen.x + deviceFramePlayInset
      : deviceFrame!.screen.x +
        (deviceFramePlayableWidth - logicalStageWidth * deviceFrameUniformScale) / 2
    : 0;
  const deviceFrameStageTop = showDeviceFrame
    ? isPlaying
      ? deviceFrame!.screen.y + deviceFramePlayInset
      : deviceFrame!.screen.y +
        (deviceFramePlayableHeight - logicalStageHeight * deviceFrameUniformScale) / 2
    : 0;
  const getPlayOverlaySurfaceStyle = (
    padding: string,
  ): React.CSSProperties => ({
    inset: showDeviceFrame ? "auto" : 0,
    left: showDeviceFrame ? deviceFrameStageLeft : undefined,
    top: showDeviceFrame ? deviceFrameStageTop : undefined,
    width: showDeviceFrame ? deviceFramePlayableWidth : undefined,
    height: showDeviceFrame ? deviceFramePlayableHeight : undefined,
    padding,
  });
  type PlayOverlay =
    | "map"
    | "inventory"
    | "crafting"
    | "questLog"
    | "skills"
    | "almanac"
    | "relationships"
    | "settings";
  const closePlayOverlays = () => {
    setIsMapOpen(false);
    setIsInventoryOpen(false);
    setIsCraftingOpen(false);
    setIsQuestLogOpen(false);
    setIsSkillsOpen(false);
    setIsAlmanacOpen(false);
    setIsRelationshipsOpen(false);
    setIsSettingsOpen(false);
  };
  const togglePlayOverlay = (overlay: PlayOverlay) => {
    const wasOpen =
      (overlay === "map" && isMapOpen) ||
      (overlay === "inventory" && isInventoryOpen) ||
      (overlay === "crafting" && isCraftingOpen) ||
      (overlay === "questLog" && isQuestLogOpen) ||
      (overlay === "skills" && isSkillsOpen) ||
      (overlay === "almanac" && isAlmanacOpen) ||
      (overlay === "relationships" && isRelationshipsOpen) ||
      (overlay === "settings" && isSettingsOpen);

    closePlayOverlays();
    if (wasOpen) return;

    switch (overlay) {
      case "map":
        setIsMapOpen(true);
        break;
      case "inventory":
        setIsInventoryOpen(true);
        break;
      case "crafting":
        setIsCraftingOpen(true);
        break;
      case "questLog":
        setIsQuestLogOpen(true);
        break;
      case "skills":
        setIsSkillsOpen(true);
        break;
      case "almanac":
        setIsAlmanacOpen(true);
        break;
      case "relationships":
        setIsRelationshipsOpen(true);
        break;
      case "settings":
        setIsSettingsOpen(true);
        break;
    }
  };
  const selectedHudConfig = selectedHudWidget
    ? getHudWidgetConfig(selectedHudWidget)
    : null;
  const selectedHudScaleX =
    selectedHudWidget === "needs"
      ? hudNeedsScaleX
      : selectedHudWidget === "skills"
        ? hudSkillsScaleX
        : hudButtonsScaleX;
  const selectedHudScaleY =
    selectedHudWidget === "needs"
      ? hudNeedsScaleY
      : selectedHudWidget === "skills"
        ? hudSkillsScaleY
        : hudButtonsScaleY;
  const selectedHudPosition = selectedHudConfig
    ? project.globalSettings[selectedHudConfig.positionKey]
    : undefined;
  const worldRulesUsesDetailPane = rpgTab === "quests";
  const rpgSystemHeader = {
    quests: {
      title: "Quests & Events",
      description:
        "Write objectives, story events, rewards, and the triggers that move the player through them.",
    },
    stats: {
      title: "Skills & Needs",
      description:
        "Define player checks and meters that dialogue, crafting, quests, and clickable objects can change.",
    },
    characters: {
      title: "Roster",
      description:
        "Manage people, groups, relationships, gifts, follower behavior, and dialogue hooks in one place.",
    },
    lore: {
      title: "Almanac",
      description:
        "Build lore, journal notes, and quest records that can be revealed by conversations, objects, or events.",
    },
    factions: {
      title: "Roster Groups",
      description:
        "Legacy group editor. Groups now live in Roster so character factions and relationships stay together.",
    },
    companions: {
      title: "Followers",
      description:
        "Legacy follower editor. Followers now live in Roster so companion logic stays attached to characters.",
    },
  }[rpgTab];

  useEffect(() => {
    if (
      editorMode === "rpg_systems" &&
      (rpgTab === "factions" || rpgTab === "companions")
    ) {
      setRpgTab("characters");
    }
  }, [editorMode, rpgTab]);

  useEffect(() => {
    if (rpgTab !== "characters") return;
    const characters = project.characters || [];
    if (characters.length === 0) {
      if (activeRosterCharacterId) setActiveRosterCharacterId(null);
      return;
    }
    if (
      !activeRosterCharacterId ||
      !characters.some((character) => character.id === activeRosterCharacterId)
    ) {
      setActiveRosterCharacterId(characters[0].id);
    }
  }, [activeRosterCharacterId, project.characters, rpgTab]);

  useEffect(() => {
    if (isPlaying || (editorMode !== "stage" && editorMode !== "ui_stage")) {
      return;
    }
    const fitForWorkspace = () => {
      if (window.innerWidth > 1200) return;
      const mainElement = document.querySelector<HTMLElement>(
        ".studio-stage-shell",
      );
      if (!mainElement) return;
      const targetWidth = showDeviceFrame
        ? deviceFrame!.outerWidth
        : logicalStageWidth;
      const targetHeight = showDeviceFrame
        ? deviceFrame!.outerHeight
        : logicalStageHeight;
      const availableWidth = Math.max(160, mainElement.clientWidth - 48);
      const availableHeight = Math.max(160, mainElement.clientHeight - 120);
      const nextZoom = Math.max(
        0.15,
        Math.min(1, availableWidth / targetWidth, availableHeight / targetHeight),
      );
      setStageZoom(Number(nextZoom.toFixed(2)));
    };
    const frameId = window.requestAnimationFrame(() =>
      window.requestAnimationFrame(fitForWorkspace),
    );
    const resizeObserver = new ResizeObserver(fitForWorkspace);
    const mainElement = document.querySelector<HTMLElement>(
      ".studio-stage-shell",
    );
    if (mainElement) resizeObserver.observe(mainElement);
    window.addEventListener("resize", fitForWorkspace);
    return () => {
      window.cancelAnimationFrame(frameId);
      resizeObserver.disconnect();
      window.removeEventListener("resize", fitForWorkspace);
    };
  }, [
    editorMode,
    isPlaying,
    logicalStageHeight,
    logicalStageWidth,
    rightSidebarWidth,
    showDeviceFrame,
    deviceFrame?.outerHeight,
    deviceFrame?.outerWidth,
  ]);

  // Auto-complete quests when all objectives are met and apply rewards
  useEffect(() => {
    if (!isPlaying) return;
    const allQuests = project.quests || [];
    const nowComplete: string[] = [];
    activeQuests.forEach((qId) => {
      if (completedQuests.includes(qId)) return;
      const quest = allQuests.find((q) => q.id === qId);
      if (!quest || !quest.objectives || quest.objectives.length === 0) return;
      const allDone = quest.objectives.every((obj) =>
        isQuestObjectiveComplete(obj, {
          playerFlags,
          playerInventory,
          currentSceneId: project.currentSceneId,
          playerSkills,
          playerTalkCounts,
          completedQuestObjectives,
        }),
      );
      if (allDone) nowComplete.push(qId);
    });
    if (nowComplete.length === 0) return;
    setActiveQuests((prev) => prev.filter((id) => !nowComplete.includes(id)));
    setCompletedQuests((prev) => [...prev, ...nowComplete]);
    // Apply rewards
    nowComplete.forEach((qId) => {
      const quest = allQuests.find((q) => q.id === qId);
      if (!quest) return;
      (quest.rewards || []).forEach((reward) => {
        if (reward.type === "give_item") {
          setPlayerInventory((prev) =>
            prev.includes(reward.targetId) ? prev : [...prev, reward.targetId],
          );
        } else if (reward.type === "set_flag") {
          setPlayerFlags((prev) =>
            prev.includes(reward.targetId) ? prev : [...prev, reward.targetId],
          );
        } else if (reward.type === "modify_status") {
          setPlayerNeeds((prev) => ({
            ...prev,
            [reward.targetId]: Math.max(
              0,
              Math.min(100, (prev[reward.targetId] ?? 50) + (reward.amount || 0)),
            ),
          }));
        }
      });
    });
  }, [isPlaying, activeQuests, completedQuests, completedQuestObjectives, playerFlags, playerInventory, playerSkills, playerTalkCounts, project.currentSceneId, project.quests]);

  const openScreenControlsEditor = () => {
    const existingMenu =
      (project.uiMenus || []).find(
        (menu) => menu.id === project.currentUiMenuId,
      ) || (project.uiMenus || [])[0];
    if (existingMenu) {
      setProject((current) => ({
        ...current,
        currentUiMenuId: existingMenu.id,
      }));
    } else {
      const newMenu: Scene = {
        id: uuidv4(),
        name: "Game Screen Controls",
        width: logicalStageWidth,
        height: logicalStageHeight,
        backgroundColor: "transparent",
        objects: [],
        blocksClicks: false,
        isOpenByDefault: false,
        closeOnClickOutside: true,
      };
      pushHistory({
        ...project,
        uiMenus: [...(project.uiMenus || []), newMenu],
        currentUiMenuId: newMenu.id,
      });
    }
    setEditorMode("ui_stage");
  };

  const openEditableHudOverlayScreen = (assetId?: string) => {
    const resolvedAssetId = assetId || project.globalSettings.hudOverlay?.assetId;
    if (!resolvedAssetId) {
      setAssetPickerCb({
        filterType: "image",
        onSelect: (id) => {
          setAssetPickerCb(null);
          openEditableHudOverlayScreen(id);
        },
      });
      return;
    }

    const asset = project.assets.find((candidate) => candidate.id === resolvedAssetId);
    if (!asset) {
      showError("Choose an overlay image first.");
      return;
    }

    const existingEditableMenu = (project.uiMenus || []).find(
      (menu) =>
        menu.name === "Editable HUD Overlay" ||
        menu.objects.some(
          (object) =>
            object.name === "HUD Overlay Artwork" &&
            object._assetId === resolvedAssetId,
        ),
    );
    if (existingEditableMenu) {
      pushHistory({
        ...project,
        currentUiMenuId: existingEditableMenu.id,
      });
      setEditorMode("ui_stage");
      setHideEditorHud(false);
      setSelectedObjectId(
        existingEditableMenu.objects.find(
          (object) => object.name === "HUD Overlay Artwork",
        )?.id || null,
      );
      showError("Opened the editable HUD overlay screen.");
      return;
    }

    const menuId = uuidv4();
    const stageW = logicalStageWidth || project.globalSettings.stageWidth || 800;
    const stageH = logicalStageHeight || project.globalSettings.stageHeight || 600;
    const overlay = project.globalSettings.hudOverlay || {};
    const overlayObject: SceneObject = {
      id: uuidv4(),
      name: "HUD Overlay Artwork",
      src: getAssetDisplaySrc(asset),
      _assetId: asset.id,
      x: 0,
      y: 0,
      width: stageW,
      height: stageH,
      rotation: 0,
      zIndex: 0,
      opacity: overlay.opacity ?? 1,
      locked: true,
      cursor: "default",
      animation: "none",
      interaction: "none",
      isVideo: false,
      isHitbox: false,
      isScript: false,
      isText: false,
      isUiElement: false,
      blendMode: normalizeBlendMode(overlay.blendMode),
      parallaxSpeed: 1,
      hasPhysics: false,
      ignoreClicks: true,
      stretchToScreen: true,
      objectFit: overlay.fit === "contain" ? "contain" : "fill",
    };
    const newMenu: Scene = {
      id: menuId,
      name: "Editable HUD Overlay",
      width: stageW,
      height: stageH,
      backgroundColor: "transparent",
      objects: [overlayObject],
      blocksClicks: false,
      isOpenByDefault: true,
      closeOnClickOutside: false,
    };

    pushHistory({
      ...project,
      uiMenus: [...(project.uiMenus || []), newMenu],
      currentUiMenuId: menuId,
      globalSettings: {
        ...project.globalSettings,
        hudOverlay: {
          ...project.globalSettings.hudOverlay,
          assetId: undefined,
        },
      },
    });
    setEditorMode("ui_stage");
    setHideEditorHud(false);
    setSelectedObjectId(overlayObject.id);
    showError("Overlay artwork is now an editable HUD screen. Drop buttons, text, images, and widgets on top of it.");
  };

